99	// PodSetReconciler reconciles a PodSet object
100	type PodSetReconciler struct {
101		client.Client
102		Scheme        *runtime.Scheme
103		EventRecorder record.EventRecorder
104		DynamicClient dynamic.Interface
105	}
106	
107	//+kubebuilder:rbac:groups=orchestration.aibrix.ai,resources=podsets,verbs=get;list;watch;create;update;patch;delete
108	//+kubebuilder:rbac:groups=orchestration.aibrix.ai,resources=podsets/status,verbs=get;update;patch
109	//+kubebuilder:rbac:groups=orchestration.aibrix.ai,resources=podsets/finalizers,verbs=update
