113	func (r *PodSetReconciler) Reconcile(ctx context.Context, req ctrl.Request) (ctrl.Result, error) {
114		klog.V(4).InfoS("Reconciling PodSet", "podset", req.NamespacedName)
115	
116		podSet := &orchestrationv1alpha1.PodSet{}
117		if err := r.Get(ctx, req.NamespacedName, podSet); err != nil {
118			if apierrors.IsNotFound(err) {
119				return ctrl.Result{}, nil
120			}
121			return ctrl.Result{}, err
122		}
123	
124		// Handle deletion
125		if !podSet.DeletionTimestamp.IsZero() {
126			return r.finalizePodSet(ctx, podSet)
127		}
128	
129		// Add finalizer if not present
130		if !controllerutil.ContainsFinalizer(podSet, PodSetFinalizer) {
131			controllerutil.AddFinalizer(podSet, PodSetFinalizer)
132			return ctrl.Result{}, r.Update(ctx, podSet)
133		}
134	
135		// Reconcile podgroup
136		if err := r.reconcilePodGroup(ctx, podSet); err != nil {
137			r.EventRecorder.Eventf(podSet, v1.EventTypeWarning, "ReconcileError", "Failed to reconcile podgroup: %v", err)
138			return ctrl.Result{}, err
139		}
140	
141		// Reconcile pods
142		if err := r.reconcilePods(ctx, podSet); err != nil {
143			r.EventRecorder.Eventf(podSet, v1.EventTypeWarning, "ReconcileError", "Failed to reconcile pods: %v", err)
144			return ctrl.Result{}, err
145		}
146	
147		// Update status
148		if err := r.updateStatus(ctx, podSet); err != nil {
149			return ctrl.Result{}, err
150		}
151	
152		return ctrl.Result{}, nil
153	}
