155	func (r *PodSetReconciler) reconcilePodGroup(ctx context.Context, podSet *orchestrationv1alpha1.PodSet) error {
156		if podSet == nil || podSet.Spec.SchedulingStrategy == nil {
157			return nil
158		}
159	
160		podGroupMeta := metav1.ObjectMeta{
161			Name:      podSet.Name,
162			Namespace: podSet.Namespace,
163			Labels: map[string]string{
164				constants.PodSetNameLabelKey: podSet.Name,
165			},
166			OwnerReferences: []metav1.OwnerReference{
167				*metav1.NewControllerRef(podSet, orchestrationv1alpha1.SchemeGroupVersion.WithKind(orchestrationv1alpha1.PodSetKind)),
168			},
169		}
170	
171		if podSet.Spec.SchedulingStrategy.GodelSchedulingStrategy != nil {
172			expectedGroup := &schedv1alpha1.PodGroup{
173				ObjectMeta: podGroupMeta,
174				Spec:       schedv1alpha1.PodGroupSpec(*podSet.Spec.SchedulingStrategy.GodelSchedulingStrategy),
175			}
176			expectedGroup.SetGroupVersionKind(schedv1alpha1.SchemeGroupVersion.WithKind("PodGroup"))
177			if synced, err := utils.EnsurePodGroup(ctx, r.DynamicClient, expectedGroup, podSet.Name, podSet.Namespace); err != nil {
178				return err
179			} else if synced {
180				r.EventRecorder.Eventf(podSet, v1.EventTypeNormal, PodGroupSyncedEventType, "pod group %s synced", podSet.Name)
181			}
182		}
183		if podSet.Spec.SchedulingStrategy.CoschedulingSchedulingStrategy != nil {
184			expectedGroup := &schedulerpluginsv1aplha1.PodGroup{
185				ObjectMeta: podGroupMeta,
186				Spec:       schedulerpluginsv1aplha1.PodGroupSpec(*podSet.Spec.SchedulingStrategy.CoschedulingSchedulingStrategy),
187			}
188			expectedGroup.SetGroupVersionKind(schedulerpluginsv1aplha1.SchemeGroupVersion.WithKind("PodGroup"))
189			if synced, err := utils.EnsurePodGroup(ctx, r.DynamicClient, expectedGroup, podSet.Name, podSet.Namespace); err != nil {
190				return err
191			} else if synced {
192				r.EventRecorder.Eventf(podSet, v1.EventTypeNormal, PodGroupSyncedEventType, "pod group %s synced", podSet.Name)
193			}
194		}
195		if podSet.Spec.SchedulingStrategy.VolcanoSchedulingStrategy != nil {
196			expectedGroup := &volcanoschedv1beta1.PodGroup{
197				ObjectMeta: podGroupMeta,
198				Spec: volcanoschedv1beta1.PodGroupSpec{
199					MinMember:         podSet.Spec.SchedulingStrategy.VolcanoSchedulingStrategy.MinMember,
200					MinTaskMember:     podSet.Spec.SchedulingStrategy.VolcanoSchedulingStrategy.MinTaskMember,
201					Queue:             podSet.Spec.SchedulingStrategy.VolcanoSchedulingStrategy.Queue,
202					PriorityClassName: podSet.Spec.SchedulingStrategy.VolcanoSchedulingStrategy.PriorityClassName,
203					MinResources:      &podSet.Spec.SchedulingStrategy.VolcanoSchedulingStrategy.MinResources,
204				},
205			}
206			expectedGroup.SetGroupVersionKind(volcanoschedv1beta1.SchemeGroupVersion.WithKind("PodGroup"))
207			if synced, err := utils.EnsurePodGroup(ctx, r.DynamicClient, expectedGroup, podSet.Name, podSet.Namespace); err != nil {
208				return err
209			} else if synced {
210				r.EventRecorder.Eventf(podSet, v1.EventTypeNormal, PodGroupSyncedEventType, "pod group %s synced", podSet.Name)
211			}
212		}
213		return nil
214	}
215	
216	func (r *PodSetReconciler) reconcilePods(ctx context.Context, podSet *orchestrationv1alpha1.PodSet) error {
217		// Get existing pods
218		podList, err := r.getPodsForPodSet(ctx, podSet)
219		if err != nil {
220			return fmt.Errorf("failed to get pods for PodSet: %w", err)
221		}
222	
223		activePods := filterActivePods(podList.Items)
224		currentPodCount := len(activePods)
225		desiredPodCount := int(podSet.Spec.PodGroupSize)
226	
227		if currentPodCount < desiredPodCount {
228			switch podSet.Spec.RecoveryPolicy {
229			case orchestrationv1alpha1.ReplaceUnhealthy:
230				return r.handleReplaceUnhealthy(ctx, podSet, activePods, currentPodCount, desiredPodCount)
231			case orchestrationv1alpha1.RecreatePodRecreateStrategy:
232				return r.handleRecreateStrategy(ctx, podSet, activePods, desiredPodCount)
233			}
234		} else if currentPodCount > desiredPodCount {
235			return r.handleScaleDown(ctx, podSet, activePods, currentPodCount, desiredPodCount)
236		}
237	
238		return nil
239	}
240	
241	func (r *PodSetReconciler) handleReplaceUnhealthy(ctx context.Context, podSet *orchestrationv1alpha1.PodSet,
242		activePods []corev1.Pod, currentPodCount, desiredPodCount int) error {
243	
244		// Proactively find and delete unhealthy pods
245		var podsToDelete []*corev1.Pod
246		for i := range activePods {
247			pod := activePods[i]
248			for _, cs := range pod.Status.ContainerStatuses {
249				if cs.RestartCount > 0 {
250					klog.InfoS("Marking pod as unhealthy due to container restarts", "pod", pod.Name, "restarts", cs.RestartCount)
251					podsToDelete = append(podsToDelete, &pod)
252					break
253				}
254			}
255		}
256		if len(podsToDelete) > 0 {
257			klog.InfoS("Found unhealthy pods to be deleted", "count", len(podsToDelete), "podset", podSet.Name)
258			for _, pod := range podsToDelete {
259				if err := r.Delete(ctx, pod); err != nil {
260					klog.ErrorS(err, "Failed to delete unhealthy pod", "pod", pod.Name)
261					continue
262				}
263			}
264			r.EventRecorder.Eventf(podSet, corev1.EventTypeNormal, "DeletingUnhealthyPods", "Deleting %d unhealthy pods due to container restarts.", len(podsToDelete))
265			return nil
266		}
267	
268		// If no unhealthy pods deleted, fill missing slots
269		if desiredPodCount-currentPodCount > 0 {
270			r.EventRecorder.Eventf(podSet, corev1.EventTypeNormal, "ReplacingUnhealthy",
271				"ReplaceUnhealthy policy: creating %d pod(s) to replace missing ones, aiming for %d total.",
272				desiredPodCount-currentPodCount, desiredPodCount)
273		}
274	
275		existingIndices := map[int]struct{}{}
276		sortPodsByIndex(activePods)
277		for _, pod := range activePods {
278			if idxStr, ok := pod.Labels[constants.PodGroupIndexLabelKey]; ok {
279				if idx, err := strconv.Atoi(idxStr); err == nil {
280					existingIndices[idx] = struct{}{}
281				}
282			}
283		}
284		for i := 0; i < desiredPodCount; i++ {
285			if _, exists := existingIndices[i]; !exists {
286				pod, err := r.createPodFromTemplate(podSet, i)
287				if err != nil {
288					return fmt.Errorf("failed to create pod template: %w", err)
289				}
290				if err := r.Create(ctx, pod); err != nil {
291					if apierrors.IsAlreadyExists(err) {
292						klog.InfoS("Pod already exists, skipping", "pod", pod.Name, "podset", podSet.Name)
293						continue
294					}
295					return fmt.Errorf("failed to create pod %v: %w", pod.Name, err)
296				}
297				klog.InfoS("Created pod (missing)", "pod", pod.Name, "podset", podSet.Name)
298			}
299		}
300		return nil
301	}
302	
303	func (r *PodSetReconciler) handleRecreateStrategy(ctx context.Context, podSet *orchestrationv1alpha1.PodSet,
304		activePods []corev1.Pod, desiredPodCount int) error {
305	
306		if len(activePods) > 0 {
307			klog.InfoS("Recreate strategy: deleting active pods", "podset", podSet.Name, "count", len(activePods))
308			r.EventRecorder.Eventf(podSet, corev1.EventTypeNormal, "RecreatingAllPods",
309				"Recreate policy triggered: deleting all %d active pods before creating new ones", len(activePods))
310			for i := range activePods {
311				if err := r.Delete(ctx, &activePods[i]); err != nil {
312					return fmt.Errorf("failed to delete pod %v: %w", activePods[i].Name, err)
313				}
314			}
315			return nil
316		}
317	
318		klog.InfoS("FullRecreate strategy: creating new pods", "podset", podSet.Name, "count", desiredPodCount)
319		for i := 0; i < desiredPodCount; i++ {
320			pod, err := r.createPodFromTemplate(podSet, i)
321			if err != nil {
322				return fmt.Errorf("failed to create pod template: %w", err)
323			}
324			if err := r.Create(ctx, pod); err != nil {
325				if apierrors.IsAlreadyExists(err) {
326					continue
327				}
328				return fmt.Errorf("failed to create pod %v: %w", pod.Name, err)
329			}
330			klog.InfoS("Created pod", "pod", pod.Name)
331		}
332		return nil
333	}
334	
335	func (r *PodSetReconciler) handleScaleDown(ctx context.Context, podSet *orchestrationv1alpha1.PodSet,
336		activePods []corev1.Pod, currentPodCount, desiredPodCount int) error {
337	
338		podsToDelete := currentPodCount - desiredPodCount
339		r.EventRecorder.Eventf(podSet, corev1.EventTypeNormal, "ScalingDown",
340			"Deleting %d excess pods to meet desired count of %d", podsToDelete, desiredPodCount)
341	
342		sortPodsByIndex(activePods)
343		for i := 0; i < podsToDelete; i++ {
344			podToDelete := activePods[len(activePods)-1-i]
345			if err := r.Delete(ctx, &podToDelete); err != nil {
346				return fmt.Errorf("failed to delete pod %s: %w", podToDelete.Name, err)
347			}
348			klog.InfoS("Deleted pod", "pod", podToDelete.Name, "podset", podSet.Name)
349		}
350		return nil
351	}
352	
353	func (r *PodSetReconciler) createPodFromTemplate(podSet *orchestrationv1alpha1.PodSet, podIndex int) (*v1.Pod, error) {
354		pod, err := ctrlutil.GetPodFromTemplate(&podSet.Spec.Template, podSet, metav1.NewControllerRef(podSet, controllerKind))
355		if err != nil {
356			return nil, err
357		}
358	
359		// Set pod name
360		pod.Name = utils.Shorten(fmt.Sprintf("%s-%d", podSet.Name, podIndex), false, false)
361		pod.Namespace = podSet.Namespace
362	
363		// Add labels
364		if pod.Labels == nil {
365			pod.Labels = make(map[string]string)
366		}
367		pod.Labels[constants.PodSetNameLabelKey] = podSet.Name
368		pod.Labels[constants.PodGroupIndexLabelKey] = strconv.Itoa(podIndex)
369	
370		// inherit podset labels and annotations
371		for k, v := range podSet.Labels {
372			if _, ok := pod.Labels[k]; !ok {
373				pod.Labels[k] = v
374			}
375		}
376		for k, v := range podSet.Annotations {
377			if _, ok := pod.Annotations[k]; !ok {
378				pod.Annotations[k] = v
379			}
380		}
381	
382		// manually set the hostname and subdomain for FQDN
383		pod.Spec.Hostname = pod.Name
384		pod.Spec.Subdomain = podSet.Labels[constants.StormServiceNameLabelKey]
385	
386		// Add environment variables for pod coordination
387		isBuiltIn := func(name string) bool {
388			return name == constants.PodSetNameEnvKey ||
389				name == constants.PodSetIndexEnvKey ||
390				name == constants.PodSetSizeEnvKey
391		}
392		addBuiltInEnvVars := func(envs []v1.EnvVar) []v1.EnvVar {
393			builtInEnvs := []v1.EnvVar{
394				{Name: constants.PodSetNameEnvKey, Value: podSet.Name},
395				{Name: constants.PodSetIndexEnvKey, Value: strconv.Itoa(podIndex)},
396				{Name: constants.PodSetSizeEnvKey, Value: strconv.Itoa(int(podSet.Spec.PodGroupSize))},
397			}
398			for _, env := range envs {
399				if isBuiltIn(env.Name) {
400					klog.Warningf("PodSet %s: dropping user-defined env var %q as it conflicts with a built-in env var",
401						podSet.Name, env.Name)
402					continue
403				}
404				builtInEnvs = append(builtInEnvs, env)
405			}
406			return builtInEnvs
407		}
408		if pod.Spec.InitContainers != nil {
409			for i := range pod.Spec.InitContainers {
410				pod.Spec.InitContainers[i].Env = addBuiltInEnvVars(pod.Spec.InitContainers[i].Env)
411			}
412		}
413		if pod.Spec.Containers != nil {
414			for i := range pod.Spec.Containers {
415				pod.Spec.Containers[i].Env = addBuiltInEnvVars(pod.Spec.Containers[i].Env)
416			}
417		}
418	
419		return pod, nil
420	}
421	
422	func (r *PodSetReconciler) getPodsForPodSet(ctx context.Context, podSet *orchestrationv1alpha1.PodSet) (*v1.PodList, error) {
423		podList := &v1.PodList{}
424		err := r.List(ctx, podList, client.InNamespace(podSet.Namespace), client.MatchingLabels{
425			constants.PodSetNameLabelKey: podSet.Name,
426		})
427		return podList, err
428	}
429	
430	func (r *PodSetReconciler) updateStatus(ctx context.Context, podSet *orchestrationv1alpha1.PodSet) error {
431		podList, err := r.getPodsForPodSet(ctx, podSet)
432		if err != nil {
433			return err
434		}
435	
436		activePods := filterActivePods(podList.Items)
437		readyPods := filterReadyPods(activePods)
438	
439		newStatus := podSet.Status.DeepCopy()
440		newStatus.TotalPods = int32(len(activePods))
441		newStatus.ReadyPods = int32(len(readyPods))
442	
443		// Determine phase
444		if len(activePods) == 0 {
445			newStatus.Phase = orchestrationv1alpha1.PodSetPhasePending
446		} else if len(readyPods) == int(podSet.Spec.PodGroupSize) {
447			newStatus.Phase = orchestrationv1alpha1.PodSetPhaseReady
448		} else if len(readyPods) > 0 {
449			newStatus.Phase = orchestrationv1alpha1.PodSetPhaseRunning
450		} else {
451			newStatus.Phase = orchestrationv1alpha1.PodSetPhasePending
452		}
453	
454		// For now, skip conditions to avoid compilation issues
455		// TODO: Add proper condition management later
456	
457		if !apiequality.Semantic.DeepEqual(&podSet.Status, newStatus) {
458			podSet.Status = *newStatus
459			return r.Status().Update(ctx, podSet)
460		}
461	
462		return nil
463	}
464	
465	func (r *PodSetReconciler) finalizePodSet(ctx context.Context, podSet *orchestrationv1alpha1.PodSet) (ctrl.Result, error) {
466		// Delete all pods
467		podSetList, err := r.getPodsForPodSet(ctx, podSet)
468		if err != nil {
469			return ctrl.Result{}, err
470		}
471	
472		if len(podSetList.Items) > 0 {
473			for _, pod := range podSetList.Items {
474				if err := r.Delete(ctx, &pod); err != nil && !apierrors.IsNotFound(err) {
475					return ctrl.Result{}, fmt.Errorf("failed to delete pod %s: %w", pod.Name, err)
476				}
477			}
478			// Wait for pods to be deleted
479			return ctrl.Result{Requeue: true}, nil
480		}
481	
482		// Delete podgroup
483		if err := utils.FinalizePodGroup(ctx, r.DynamicClient, r.Client, &schedv1alpha1.PodGroup{}, podSet.Name, podSet.Namespace); err != nil {
484			return ctrl.Result{RequeueAfter: DefaultRequeueAfter}, err
485		}
486		if err := utils.FinalizePodGroup(ctx, r.DynamicClient, r.Client, &schedulerpluginsv1aplha1.PodGroup{}, podSet.Name, podSet.Namespace); err != nil {
487			return ctrl.Result{RequeueAfter: DefaultRequeueAfter}, err
488		}
489		if err := utils.FinalizePodGroup(ctx, r.DynamicClient, r.Client, &volcanoschedv1beta1.PodGroup{}, podSet.Name, podSet.Namespace); err != nil {
490			return ctrl.Result{RequeueAfter: DefaultRequeueAfter}, err
491		}
492	
493		// Remove finalizer
494		controllerutil.RemoveFinalizer(podSet, PodSetFinalizer)
495		return ctrl.Result{}, r.Update(ctx, podSet)
496	}
497	
498	// Helper functions
499	func filterActivePods(pods []v1.Pod) []v1.Pod {
500		var active []v1.Pod
501		for _, pod := range pods {
502			if pod.Status.Phase != v1.PodSucceeded && pod.Status.Phase != v1.PodFailed {
503				active = append(active, pod)
504			}
505		}
506		return active
507	}
508	
509	func filterReadyPods(pods []v1.Pod) []v1.Pod {
510		var ready []v1.Pod
511		for _, pod := range pods {
512			if podutil.IsPodReady(&pod) {
513				ready = append(ready, pod)
514			}
515		}
516		return ready
517	}
518	
519	// getPodIndexFromLabels safely extracts pod index from labels
520	// If index label is missing or invalid, return a large number to push it to the end.
521	func getPodIndexFromLabels(pod v1.Pod) int {
522		if idxStr, ok := pod.Labels[constants.PodGroupIndexLabelKey]; ok {
523			if idx, err := strconv.Atoi(idxStr); err == nil {
524				return idx
525			}
526		}
527		// return a big number so invalid pods are always sorted last
528		return int(^uint(0) >> 1) // max int
529	}
530	
531	// sortPodsByIndex sorts pods in ascending order of their PodGroupIndex
532	func sortPodsByIndex(pods []v1.Pod) {
533		sort.Slice(pods, func(i, j int) bool {
534			return getPodIndexFromLabels(pods[i]) < getPodIndexFromLabels(pods[j])
535		})
536	}
537

