40	func (r *StormServiceReconciler) sync(ctx context.Context, stormService *orchestrationv1alpha1.StormService, currentRevision *apps.ControllerRevision, updateRevision *apps.ControllerRevision, collisionCount int32) (time.Duration, error) {
41		current, err := applyRevision(stormService, currentRevision)
42		if err != nil {
43			return 0, err
44		}
45	
46		// reconcile headless service
47		if err := r.syncHeadlessService(ctx, stormService); err != nil {
48			return 0, fmt.Errorf("sync headless service error %v", err)
49		}
50	
51		var reconcileErr error
52		// 1. reconcile the number of roleSets to meet the spec.Replicas, both currentRevision and updateRevision
53		if scaling, err := r.scaling(ctx, stormService, current, currentRevision, updateRevision); err != nil {
54			r.EventRecorder.Eventf(stormService, corev1.EventTypeWarning, ScalingEventType, "scaling error %s", err.Error())
55			reconcileErr = err
56		} else if !stormService.Spec.Paused && !scaling { // skip rollout when paused and in scaling
57			// 2. check the rollout progress
58			reconcileErr = r.rollout(ctx, stormService, current, currentRevision, updateRevision)
59			if reconcileErr != nil {
60				r.EventRecorder.Eventf(stormService, corev1.EventTypeWarning, RolloutEventType, "rollout error %s", reconcileErr.Error())
61			}
62		}
63		// 3. update status
64		if ready, err := r.updateStatus(ctx, stormService, reconcileErr, currentRevision, updateRevision, collisionCount); err != nil {
65			klog.Errorf("failed to update status for stormservice %s/%s, err: %v", stormService.Namespace, stormService.Name, err)
66			return 0, err
67		} else if !ready {
68			return DefaultRequeueAfter, nil
69		}
70		return 0, nil
71	}
72	
73	func (r *StormServiceReconciler) syncHeadlessService(ctx context.Context, service *orchestrationv1alpha1.StormService) error {
74		expectedService := &corev1.Service{
75			ObjectMeta: metav1.ObjectMeta{
76				Name:      service.Name,
77				Namespace: service.Namespace,
78				Labels:    service.Labels,
79				OwnerReferences: []metav1.OwnerReference{
80					*metav1.NewControllerRef(service, orchestrationv1alpha1.SchemeGroupVersion.WithKind(orchestrationv1alpha1.StormServiceKind)),
81				},
82			},
83			Spec: corev1.ServiceSpec{
84				Type:                     corev1.ServiceTypeClusterIP,
85				ClusterIP:                corev1.ClusterIPNone,
86				Selector:                 map[string]string{constants.StormServiceNameLabelKey: service.Name},
87				PublishNotReadyAddresses: true,
88			},
89		}
90	
91		headlessService := &corev1.Service{}
92		err := r.Client.Get(ctx, client.ObjectKey{Name: service.Name, Namespace: service.Namespace}, headlessService)
93		if err != nil {
94			if errors.IsNotFound(err) {
95				// service doesn't exist, create it
96				if createErr := r.Client.Create(ctx, expectedService); createErr != nil {
97					return fmt.Errorf("failed to create headless service: %w", createErr)
98				}
99				r.EventRecorder.Eventf(service, corev1.EventTypeNormal, HeadlessServiceEventType, "Headless Service(discovery) %s created", service.Name)
100				return nil
101			}
102			return err // Return other errors immediately
103		}
104	
105		if !isServiceEqual(headlessService, expectedService) {
106			headlessService.Spec = expectedService.Spec
107			if err := r.Client.Update(ctx, headlessService); err != nil {
108				return fmt.Errorf("failed to update headless service: %w", err)
109			}
110			r.EventRecorder.Eventf(service, corev1.EventTypeNormal, HeadlessServiceEventType, "Headless Service %s updated", service.Name)
111		}
112		return nil
113	}
114	
115	func calculateReplicas(desiredReplica, current, updated int32) (desiredCurrent int32, desiredUpdated int32) {
116		if desiredReplica == current+updated {
117			return current, updated
118		}
119		currentTotal := current + updated
120		if currentTotal != 0 {
121			desiredCurrent = integer.RoundToInt32(float64(current*desiredReplica) / float64(currentTotal))
122			desiredUpdated = integer.RoundToInt32(float64(updated*desiredReplica) / float64(currentTotal))
123		}
124		// 1. if current == updated == 0, scaling out updated
125		// 2. overcome the rounding error
126		if desiredCurrent+desiredUpdated != desiredReplica {
127			desiredUpdated = desiredReplica - desiredCurrent
128		}
129		return
130	}
131	
132	// Scaling: adjust the number of RoleSets to match spec.Replicas. There are several scenarios that may lead to a mismatch:
133	// 1. The user modifies spec.Replicas, causing too few or too many RoleSets.
134	// 2. During the rollout process, new RoleSets may be created or old ones deleted.
135	// 3. RoleSets may be unexpectedly created or deleted.
136	// Note: Due to the presence of maxUnavailable, this function does not guarantee that the number of RoleSets
137	// will exactly match spec.Replicas upon return — multiple scaling adjustments may be required.
138	func (r *StormServiceReconciler) scaling(ctx context.Context, stormService, current *orchestrationv1alpha1.StormService, currentCR, updateCR *apps.ControllerRevision) (bool, error) {
139		currentRevision := currentCR.Name
140		updatedRevision := updateCR.Name
141		var scaling bool
142		allRoleSets, err := r.getRoleSetList(ctx, stormService.Spec.Selector)
143		if err != nil {
144			return false, err
145		}
146		// skip scaling when there are terminating roleSets
147		activeRoleSets, _ := filterTerminatingRoleSets(allRoleSets)
148		var expectReplica int32
149		if stormService.Spec.Replicas != nil {
150			expectReplica = *stormService.Spec.Replicas
151		}
152		minAvailable := MinAvailable(stormService)
153		maxSurge := MaxSurge(stormService)
154		diff := len(activeRoleSets) - int(expectReplica)
155		if diff < 0 {
156			// 1. scale out
157			diff = -diff
158			if currentRevision == updatedRevision || !stormService.Spec.Paused {
159				// 1.1: Two cases fall into this branch:
160				// 1.1.1 Only one revision exists, and the number of RoleSets is insufficient — scale out the difference directly.
161				// 1.1.2 A rollout is in progress, and some old RoleSets have been deleted — prioritize scaling out the updated revision.
162				// Do not exceed maxSurge when scaling out.
163				createBudget := utils.MinInt(diff, int(expectReplica+maxSurge-int32(len(allRoleSets))))
164				klog.Infof("scaling out stormservice %s/%s, diff: %d, minAvailable: %d, maxSurge: %d, using revision %s, createBudget %d", stormService.Namespace, stormService.Name, diff, minAvailable, maxSurge, updatedRevision, createBudget)
165				// Compute per-role revisions for creating new RoleSets
166				roleRevisions := computeRoleRevisions(current, stormService, currentCR, updateCR)
167				count, err := r.createRoleSet(stormService, createBudget, updatedRevision, roleRevisions)
168				if err != nil {
169					return false, err
170				}
171				scaling = scaling || count > 0
172				klog.Infof("%s/%s successfully create %d roleSets, revision %s", stormService.Namespace, stormService.Name, count, updatedRevision)
173			} else {
174				// 1.2: Two revisions exist, and the number of RoleSets is insufficient — scale out both revisions proportionally.
175				// TODO: currentRevisionSets may actually contain multiple revisions. For now, we treat them all as currentRevision.
176				//       Revisit this logic for finer handling if needed in the future.
177				updatedRevisionSets, currentRevisionSets := filterRoleSetByRevision(activeRoleSets, updatedRevision)
178				expectCurrentReplica, expectUpdatedReplica := calculateReplicas(expectReplica, stormService.Status.CurrentReplicas, stormService.Status.UpdatedReplicas)
179				klog.Infof("scaling out stormservice %s/%s, current revision %s, updated revision %s, currentReplica %d, updatedReplica %d, expectCurrentReplica: %d, expectUpdatedReplica: %d", stormService.Namespace, stormService.Name, currentRevision, updatedRevision, len(currentRevisionSets), len(updatedRevisionSets), expectCurrentReplica, expectUpdatedReplica)
180				// For current revision, all roles use currentCR
181				currentRoleRevisions := computeRoleRevisions(current, current, currentCR, currentCR)
182				currentCreated, err := r.createRoleSet(current, int(expectCurrentReplica)-len(currentRevisionSets), currentRevision, currentRoleRevisions)
183				if err != nil {
184					return false, err
185				}
186				// For updated revision, compute per-role revisions
187				updatedRoleRevisions := computeRoleRevisions(current, stormService, currentCR, updateCR)
188				updatedCreated, err := r.createRoleSet(stormService, int(expectUpdatedReplica)-len(updatedRevisionSets), updatedRevision, updatedRoleRevisions)
189				if err != nil {
190					return false, err
191				}
192				scaling = scaling || currentCreated > 0 || updatedCreated > 0
193				klog.Infof("%s/%s successfully create %d roleSets in current revision, %d rolesets in updated revision", stormService.Namespace, stormService.Name, currentCreated, updatedCreated)
194			}
195		} else if diff > 0 {
196			// 2. scale in
197			if currentRevision == updatedRevision || !stormService.Spec.Paused {
198				// 2.1 Two cases fall into this branch:
199				// 2.1.1 Only one revision exists and the number of RoleSets exceeds spec.Replicas — scale in by 'diff' based on readiness.
200				// 2.1.2 Rollout is in progress and new RoleSets are already created — scale in old RoleSets first based on maxUnavailable.
201				ready, _ := filterReadyRoleSets(activeRoleSets)
202				readyCount := len(ready)
203				klog.Infof("scaling in stormservice %s/%s, diff: %d, minAvailable: %d, maxSurge: %d, currentReady: %d", stormService.Namespace, stormService.Name, diff, minAvailable, maxSurge, readyCount)
204				sortRoleSetByRevision(activeRoleSets, updatedRevision)
205				var toDelete []*orchestrationv1alpha1.RoleSet
206				for i := 0; i < len(activeRoleSets); i++ {
207					if diff == 0 {
208						break
209					}
210					if utils.IsRoleSetReady(activeRoleSets[i]) && readyCount <= int(minAvailable) {
211						break
212					}
213					toDelete = append(toDelete, activeRoleSets[i])
214					if utils.IsRoleSetReady(activeRoleSets[i]) {
215						readyCount--
216					}
217					diff--
218				}
219				count, err := r.deleteRoleSet(toDelete)
220				if err != nil {
221					return false, err
222				}
223				scaling = scaling || count > 0
224				klog.Infof("%s/%s successfully delete %d roleSets", stormService.Namespace, stormService.Name, count)
225			} else {
226				// 2.2 Two revisions exist and the rollout is paused — scale in both revisions proportionally.
227				// 2.2.1 Prioritize deleting notReady RoleSets
228				ready, notReady := filterReadyRoleSets(activeRoleSets)
229				klog.Infof("scaling in stormservice %s/%s in pause, diff: %d, minAvailable: %d, maxSurge: %d, ready roleSet: %d, not ready roleSets: %d", stormService.Namespace, stormService.Name, diff, minAvailable, maxSurge, len(ready), len(notReady))
230				var toDelete []*orchestrationv1alpha1.RoleSet
231				if diff <= len(notReady) {
232					toDelete = notReady[:diff]
233					count, err := r.deleteRoleSet(toDelete)
234					if err != nil {
235						return false, err
236					}
237					klog.Infof("%s/%s successfully delete %d roleSets", stormService.Namespace, stormService.Name, count)
238					return false, nil
239				} else {
240					toDelete = append(toDelete, notReady...)
241					diff -= len(notReady)
242					// TODO: note: diff is not being used in following logic, log a comment for short term, correct me!
243					klog.Infof("current diff is %d", diff)
244				}
245				// 2.2.2 Continue scaling in ready RoleSets proportionally
246				updatedReady, currentReady := filterRoleSetByRevision(ready, updatedRevision)
247				expectCurrentReplica, expectUpdatedReplica := calculateReplicas(expectReplica, int32(len(currentReady)), int32(len(updatedReady)))
248				toDelete = append(toDelete, currentReady[:len(currentReady)-int(expectCurrentReplica)]...)
249				toDelete = append(toDelete, updatedReady[:len(updatedReady)-int(expectUpdatedReplica)]...)
250				count, err := r.deleteRoleSet(toDelete)
251				if err != nil {
252					return false, err
253				}
254				scaling = scaling || count > 0
255				klog.Infof("%s/%s successfully delete %d roleSets", stormService.Namespace, stormService.Name, count)
256			}
257		}
258		return scaling, nil
259	}
260	
261	// Rollout: execute the deployment update logic with per-role revision tracking
262	func (r *StormServiceReconciler) rollout(ctx context.Context, stormService, current *orchestrationv1alpha1.StormService, currentCR, updateCR *apps.ControllerRevision) error {
263		allRoleSets, err := r.getRoleSetList(ctx, stormService.Spec.Selector)
264		if err != nil {
265			return err
266		}
267		var expectReplica int32
268		if stormService.Spec.Replicas != nil {
269			expectReplica = *stormService.Spec.Replicas
270		}
271		updated, _ := filterRoleSetByRevision(allRoleSets, updateCR.Name)
272		if len(updated) == int(expectReplica) {
273			return nil
274		}
275		switch stormService.Spec.UpdateStrategy.Type {
276		case "":
277			// By default use RollingUpdate strategy
278			fallthrough
279		case orchestrationv1alpha1.RollingUpdateStormServiceStrategyType:
280			return r.rollingUpdate(allRoleSets, stormService, current, currentCR, updateCR)
281		case orchestrationv1alpha1.InPlaceUpdateStormServiceStrategyType:
282			return r.inPlaceUpdate(allRoleSets, stormService, current, currentCR, updateCR)
283		default:
284			return fmt.Errorf("unexpected stormService strategy type: %s", stormService.Spec.UpdateStrategy.Type)
285		}
286	}
287	
288	// rollingUpdate: rolling update logic for replica mode
289	// The update is triggered by intentionally breaking the condition roleSet count == spec.Replicas,
290	// introducing controlled disturbances such as:
291	// 1. Creating new RoleSets with the updated revision
292	// 2. Deleting old RoleSets with the previous revision
293	// The entire process adheres to MaxSurge and MaxUnavailable constraints
294	func (r *StormServiceReconciler) rollingUpdate(allRoleSets []*orchestrationv1alpha1.RoleSet, stormService, current *orchestrationv1alpha1.StormService, currentCR, updateCR *apps.ControllerRevision) error {
295		updatedRevision := updateCR.Name
296		minAvailable := MinAvailable(stormService)
297		activeRoleSets, _ := filterTerminatingRoleSets(allRoleSets)
298		ready, _ := filterReadyRoleSets(activeRoleSets)
299		readyCount := len(ready)
300		maxSurge := MaxSurge(stormService)
301		klog.Infof("rolling update for stormservice %s/%s, updatedRevision %s, currReady %d, minAvailable %d, maxSurge %d", stormService.Namespace, stormService.Name, updatedRevision, len(ready), minAvailable, maxSurge)
302	
303		// 1. delete outdated roleset, follow the max unavailable rule
304		updated, outdated := filterRoleSetByRevision(activeRoleSets, updatedRevision)
305		sortRoleSetByRevision(outdated, updatedRevision)
306		var toDelete []*orchestrationv1alpha1.RoleSet
307		for i := 0; i < len(outdated); i++ {
308			if utils.IsRoleSetReady(outdated[i]) && readyCount <= int(minAvailable) {
309				break
310			}
311			toDelete = append(toDelete, outdated[i])
312			if utils.IsRoleSetReady(outdated[i]) {
313				readyCount--
314			}
315		}
316		_, err := r.deleteRoleSet(toDelete)
317		if err != nil {
318			return err
319		}
320	
321		// 2. create roleset, follow the max surge rule
322		var expectedReplica int
323		if stormService.Spec.Replicas != nil {
324			expectedReplica = int(*stormService.Spec.Replicas)
325		}
326		surge := utils.MinInt(expectedReplica+int(maxSurge)-len(allRoleSets), expectedReplica-len(updated))
327		if surge < 0 {
328			surge = 0
329		}
330		// Compute per-role revisions for rolling update (for consistency with InPlaceUpdate)
331		roleRevisions := computeRoleRevisions(current, stormService, currentCR, updateCR)
332		_, err = r.createRoleSet(stormService, surge, updatedRevision, roleRevisions)
333		if err != nil {
334			return err
335		}
336		return nil
337	}
338	
339	// inPlaceUpdate: logic for in-place updates in pooled mode with per-role revision tracking
340	// Propagate changes from the StormService to all associated RoleSets
341	func (r *StormServiceReconciler) inPlaceUpdate(allRoleSets []*orchestrationv1alpha1.RoleSet, stormService, current *orchestrationv1alpha1.StormService, currentCR, updateCR *apps.ControllerRevision) error {
342		// Compute per-role revisions
343		roleRevisions := computeRoleRevisions(current, stormService, currentCR, updateCR)
344	
345		// Update all RoleSets with per-role revision info
346		_, outdated := filterRoleSetByRevision(allRoleSets, updateCR.Name)
347		if _, err := r.updateRoleSet(stormService, outdated, updateCR.Name, roleRevisions); err != nil {
348			return err
349		}
350		return nil
351	}
352	
353	func (r *StormServiceReconciler) updateStatus(ctx context.Context, stormService *orchestrationv1alpha1.StormService, reconcileErr error, currentRevision *apps.ControllerRevision, updateRevision *apps.ControllerRevision, collisionCount int32) (bool, error) {
354		checkpoint := stormService.Status.DeepCopy()
355	
356		stormService.Status.ObservedGeneration = stormService.Generation
357		stormService.Status.CurrentRevision = currentRevision.Name
358		stormService.Status.UpdateRevision = updateRevision.Name
359		stormService.Status.CollisionCount = &collisionCount
360		if reconcileErr != nil {
361			condition := []orchestrationv1alpha1.Condition{
362				*utils.NewCondition(orchestrationv1alpha1.StormServiceReplicaFailure, corev1.ConditionTrue, "Failure", reconcileErr.Error()),
363			}
364			stormService.Status.Conditions = condition
365			err := r.Client.Status().Update(ctx, stormService)
366			return false, err
367		}
368		allRoleSets, err := r.getRoleSetList(ctx, stormService.Spec.Selector)
369		if err != nil {
370			return false, err
371		}
372		stormService.Status.Replicas = int32(len(allRoleSets))
373		stormService.Status.CurrentReplicas = 0
374		stormService.Status.UpdatedReplicas = 0
375		stormService.Status.UpdatedReadyReplicas = 0
376		for _, rs := range allRoleSets {
377			if isRoleSetMatchRevision(rs, currentRevision.Name) {
378				stormService.Status.CurrentReplicas++
379			}
380			if isRoleSetMatchRevision(rs, updateRevision.Name) && isAllRoleUpdated(rs) {
381				stormService.Status.UpdatedReplicas++
382			}
383			if isRoleSetMatchRevision(rs, updateRevision.Name) && utils.IsRoleSetReady(rs) && isAllRoleUpdatedAndReady(rs) {
384				stormService.Status.UpdatedReadyReplicas++
385			}
386		}
387		if stormService.Status.CurrentReplicas == 0 {
388			stormService.Status.CurrentReplicas = stormService.Status.UpdatedReplicas
389			stormService.Status.CurrentRevision = stormService.Status.UpdateRevision
390		}
391		ready, notReady := filterReadyRoleSets(allRoleSets)
392		stormService.Status.ReadyReplicas = int32(len(ready))
393		stormService.Status.NotReadyReplicas = int32(len(notReady))
394		// set conditions
395		var specReplica int32
396		if stormService.Spec.Replicas != nil {
397			specReplica = *stormService.Spec.Replicas
398		}
399		stormServiceReady := stormService.Status.ReadyReplicas >= specReplica &&
400			stormService.Status.UpdatedReplicas == *stormService.Spec.Replicas &&
401			stormService.Status.Replicas == *stormService.Spec.Replicas &&
402			stormService.Status.CurrentRevision == stormService.Status.UpdateRevision
403		if stormServiceReady {
404			stormService.Status.Conditions = []orchestrationv1alpha1.Condition{
405				*utils.NewCondition(orchestrationv1alpha1.StormServiceReady, corev1.ConditionTrue, "Ready", ""),
406			}
407		} else {
408			stormService.Status.Conditions = []orchestrationv1alpha1.Condition{
409				*utils.NewCondition(orchestrationv1alpha1.StormServiceProgressing, corev1.ConditionTrue, "Processing", ""),
410			}
411		}
412		// support scale sub resources.
413		// TODO: add pod template hash to avoid errors during upgrade.
414		stormService.Status.ScalingTargetSelector = fmt.Sprintf("%s=%s", constants.StormServiceNameLabelKey, stormService.Name)
415	
416		// Aggregate role statuses from all RoleSets for both pool and replica modes
417		// Updated* fields will only count pods from RoleSets matching the target revision
418		stormService.Status.RoleStatuses = aggregateRoleStatuses(allRoleSets, updateRevision.Name)
419	
420		if !apiequality.Semantic.DeepEqual(checkpoint, &stormService.Status) {
421			err = utils.UpdateStatus(ctx, r.Scheme, r.Client, stormService)
422			if err != nil {
423				return false, err
424			}
425		}
426		return stormServiceReady, nil
427	}
428	
429	func (r *StormServiceReconciler) finalize(ctx context.Context, stormService *orchestrationv1alpha1.StormService) (bool, error) {
430		// check if all rolesets are deleted
431		allRoleSets, err := r.getRoleSetList(ctx, stormService.Spec.Selector)
432		if err != nil {
433			return false, err
434		}
435		if len(allRoleSets) > 0 {
436			// delete rolesets
437			if _, err := r.deleteRoleSet(allRoleSets); err != nil {
438				return false, err
439			}
440			return false, nil
441		}
442		// remove finalizer
443		if controllerutil.ContainsFinalizer(stormService, StormServiceFinalizer) {
444			if err := utils.Patch(ctx, r.Client, stormService, patch.RemoveFinalizerPatch(stormService, StormServiceFinalizer)); err != nil {
445				return false, err
446			}
447		}
448		return true, nil
449	}
