41	func (r *RoleSetReconciler) syncPodGroup(ctx context.Context, roleSet *orchestrationv1alpha1.RoleSet, spec *orchestrationv1alpha1.RoleSetSpec) error {
42		if spec.SchedulingStrategy == nil {
43			return nil
44		}
45	
46		podGroupMeta := metav1.ObjectMeta{
47			Name:      roleSet.Name,
48			Namespace: roleSet.Namespace,
49			Labels: map[string]string{
50				constants.RoleSetNameLabelKey: roleSet.Name,
51			},
52			OwnerReferences: []metav1.OwnerReference{
53				*metav1.NewControllerRef(roleSet, orchestrationv1alpha1.SchemeGroupVersion.WithKind(orchestrationv1alpha1.RoleSetKind)),
54			},
55		}
56	
57		if spec.SchedulingStrategy.GodelSchedulingStrategy != nil {
58			expectedGroup := &schedv1alpha1.PodGroup{
59				ObjectMeta: podGroupMeta,
60				Spec:       schedv1alpha1.PodGroupSpec(*spec.SchedulingStrategy.GodelSchedulingStrategy),
61			}
62			expectedGroup.SetGroupVersionKind(schedv1alpha1.SchemeGroupVersion.WithKind("PodGroup"))
63			if synced, err := utils.EnsurePodGroup(ctx, r.DynamicClient, expectedGroup, roleSet.Name, roleSet.Namespace); err != nil {
64				return err
65			} else if synced {
66				r.EventRecorder.Eventf(roleSet, v1.EventTypeNormal, PodGroupSyncedEventType, "pod group %s synced", roleSet.Name)
67			}
68		}
69		if spec.SchedulingStrategy.CoschedulingSchedulingStrategy != nil {
70			expectedGroup := &schedulerpluginsv1aplha1.PodGroup{
71				ObjectMeta: podGroupMeta,
72				Spec:       schedulerpluginsv1aplha1.PodGroupSpec(*spec.SchedulingStrategy.CoschedulingSchedulingStrategy),
73			}
74			expectedGroup.SetGroupVersionKind(schedulerpluginsv1aplha1.SchemeGroupVersion.WithKind("PodGroup"))
75			if synced, err := utils.EnsurePodGroup(ctx, r.DynamicClient, expectedGroup, roleSet.Name, roleSet.Namespace); err != nil {
76				return err
77			} else if synced {
78				r.EventRecorder.Eventf(roleSet, v1.EventTypeNormal, PodGroupSyncedEventType, "pod group %s synced", roleSet.Name)
79			}
80		}
81		if spec.SchedulingStrategy.VolcanoSchedulingStrategy != nil {
82			expectedGroup := &volcanoschedv1beta1.PodGroup{
83				ObjectMeta: podGroupMeta,
84				Spec: volcanoschedv1beta1.PodGroupSpec{
85					MinMember:         spec.SchedulingStrategy.VolcanoSchedulingStrategy.MinMember,
86					MinTaskMember:     spec.SchedulingStrategy.VolcanoSchedulingStrategy.MinTaskMember,
87					Queue:             spec.SchedulingStrategy.VolcanoSchedulingStrategy.Queue,
88					PriorityClassName: spec.SchedulingStrategy.VolcanoSchedulingStrategy.PriorityClassName,
89					MinResources:      &spec.SchedulingStrategy.VolcanoSchedulingStrategy.MinResources,
90				},
91			}
92			expectedGroup.SetGroupVersionKind(volcanoschedv1beta1.SchemeGroupVersion.WithKind("PodGroup"))
93			if synced, err := utils.EnsurePodGroup(ctx, r.DynamicClient, expectedGroup, roleSet.Name, roleSet.Namespace); err != nil {
94				return err
95			} else if synced {
96				r.EventRecorder.Eventf(roleSet, v1.EventTypeNormal, PodGroupSyncedEventType, "pod group %s synced", roleSet.Name)
97			}
98		}
99		return nil
100	}
