102	func (r *RoleSetReconciler) syncPods(ctx context.Context, roleSet *orchestrationv1alpha1.RoleSet) error {
103		var manager RollingManager
104		switch roleSet.Spec.UpdateStrategy {
105		case orchestrationv1alpha1.SequentialRoleSetStrategyType:
106			manager = &RollingManagerSequential{
107				cli:      r.Client,
108				recorder: r.EventRecorder,
109			}
110		case orchestrationv1alpha1.ParallelRoleSetUpdateStrategyType:
111			manager = &RollingManagerParallel{
112				cli:      r.Client,
113				recorder: r.EventRecorder,
114			}
115		case orchestrationv1alpha1.InterleaveRoleSetStrategyType:
116			manager = &RollingManagerInterleave{
117				cli:      r.Client,
118				recorder: r.EventRecorder,
119			}
120		default:
121			manager = &RollingManagerSequential{
122				cli:      r.Client,
123				recorder: r.EventRecorder,
124			}
125		}
126		return manager.Next(ctx, roleSet)
127	}
