129	func (r *RoleSetReconciler) calculateStatus(ctx context.Context, rs *orchestrationv1alpha1.RoleSet, managedErrors []error) (*orchestrationv1alpha1.RoleSetStatus, error) {
130		newStatus := rs.Status.DeepCopy()
131		newStatus.Roles = nil
132		var notReadyRoles []string
133		for _, role := range rs.Spec.Roles {
134			if roleStatus, err := r.calculateStatusForRole(ctx, rs, &role); err != nil {
135				// TODO: add into condition
136				klog.Warningf("Failed to calculate status for role %s: %v", role.Name, err)
137				continue
138			} else {
139				newStatus.Roles = append(newStatus.Roles, *roleStatus)
140				if roleStatus.ReadyReplicas < *role.Replicas {
141					notReadyRoles = append(notReadyRoles, role.Name)
142				}
143			}
144		}
145	
146		if len(notReadyRoles) > 0 {
147			notReadyCondition := utils.NewCondition(orchestrationv1alpha1.RoleSetReady, v1.ConditionFalse, "roleset is not ready", fmt.Sprintf("role %s is not ready", strings.Join(notReadyRoles, ",")))
148			SetRoleSetCondition(newStatus, *notReadyCondition)
149		} else {
150			readyCondition := utils.NewCondition(orchestrationv1alpha1.RoleSetReady, v1.ConditionTrue, "roleset is ready", "")
151			SetRoleSetCondition(newStatus, *readyCondition)
152		}
153	
154		failureCond := utils.GetCondition(rs.Status.Conditions, orchestrationv1alpha1.RoleSetReplicaFailure)
155		if len(managedErrors) != 0 && failureCond == nil {
156			cond := utils.NewCondition(orchestrationv1alpha1.RoleSetReplicaFailure, v1.ConditionTrue, "reconcile roleset error", fmt.Sprintf("%+v", managedErrors))
157			SetRoleSetCondition(newStatus, *cond)
158		} else if len(managedErrors) == 0 && failureCond != nil {
159			RemoveRoleSetCondition(newStatus, orchestrationv1alpha1.RoleSetReplicaFailure)
160		}
161		// TODO: what if new errors added and failureCond is not nil. can it reflect the new errors?
162		return newStatus, nil
163	}
164	
165	func (r *RoleSetReconciler) calculateStatusForRole(ctx context.Context, rs *orchestrationv1alpha1.RoleSet, role *orchestrationv1alpha1.RoleSpec) (*orchestrationv1alpha1.RoleStatus, error) {
166		// Check if this role uses PodSet (podGroupSize > 1)
167		if role.PodGroupSize != nil && *role.PodGroupSize > 1 {
168			// Use PodSet-based status calculation
169			roleStatus, err := r.calculateStatusFromPodSets(ctx, rs, role)
170			if err != nil {
171				klog.Warningf("Failed to get PodSet status for role %s in RoleSet %s/%s: %v", role.Name, rs.Namespace, rs.Name, err)
172				// Fall back to zero values
173				return nil, err
174			}
175			return roleStatus, nil
176		}
177	
178		// Use traditional pod-based status calculation for podGroupSize <= 1
179		allPods := &v1.PodList{}
180		if err := r.Client.List(ctx, allPods, client.InNamespace(rs.Namespace), client.MatchingLabels{
181			constants.RoleSetNameLabelKey: rs.Name,
182		}); err != nil {
183			return nil, err
184		}
185		var pods []*v1.Pod
186		for i := range allPods.Items {
187			pods = append(pods, &allPods.Items[i])
188		}
189		pods = filterRolePods(role, pods)
190		pods, _ = filterActivePods(pods)
191		readyReplicas := GetReadyReplicaCountForRole(pods)
192		updated, _ := filterUpdatedPods(pods, ctrlutil.ComputeHash(&role.Template, nil))
193		updatedReplicas := len(updated)
194		updatedReadyReplicas := GetReadyReplicaCountForRole(updated)
195		totalReplicas := len(pods)
196		notReadyReplicas := totalReplicas - int(readyReplicas)
197		return &orchestrationv1alpha1.RoleStatus{
198			Name:                 role.Name,
199			Replicas:             int32(totalReplicas),
200			ReadyReplicas:        readyReplicas,
201			NotReadyReplicas:     int32(notReadyReplicas),
202			UpdatedReplicas:      int32(updatedReplicas),
203			UpdatedReadyReplicas: updatedReadyReplicas,
204		}, nil
205	}
206	
207	func (r *RoleSetReconciler) calculateStatusFromPodSets(ctx context.Context, rs *orchestrationv1alpha1.RoleSet, role *orchestrationv1alpha1.RoleSpec) (*orchestrationv1alpha1.RoleStatus, error) {
208		// Get PodSets for this role
209		podSetList := &orchestrationv1alpha1.PodSetList{}
210		err := r.Client.List(ctx, podSetList, client.InNamespace(rs.Namespace), client.MatchingLabels{
211			constants.RoleSetNameLabelKey: rs.Name,
212			constants.RoleNameLabelKey:    role.Name,
213		})
214		if err != nil {
215			return nil, err
216		}
217	
218		var totalReplicas, readyReplicas int32
219		currentHash := ctrlutil.ComputeHash(&role.Template, nil)
220		var updatedReplicas, updatedReadyReplicas int32
221	
222		for _, podSet := range podSetList.Items {
223			totalReplicas++
224			if isPodSetActive(&podSet) && isPodSetReady(&podSet) {
225				readyReplicas++
226			}
227	
228			// Check if PodSet is updated (has current template hash)
229			if podSet.Labels[constants.RoleTemplateHashLabelKey] == currentHash {
230				updatedReplicas++
231				if isPodSetReady(&podSet) {
232					updatedReadyReplicas++
233				}
234			}
235		}
236	
237		klog.V(4).Infof("roleName: %s, totalReplicas: %d, readyReplicas: %d, updatedReplicas: %d, updatedReadyReplicas: %d",
238			role.Name, totalReplicas, readyReplicas, updatedReplicas, updatedReadyReplicas)
239		return &orchestrationv1alpha1.RoleStatus{
240			Name:                 role.Name,
241			Replicas:             totalReplicas,
242			ReadyReplicas:        readyReplicas,
243			NotReadyReplicas:     totalReplicas - readyReplicas,
244			UpdatedReplicas:      updatedReplicas,
245			UpdatedReadyReplicas: updatedReadyReplicas,
246		}, nil
247	}
248	
249	func (r *RoleSetReconciler) finalize(ctx context.Context, roleSet *orchestrationv1alpha1.RoleSet) (bool, error) {
250		selectorOpt := client.MatchingLabels{constants.RoleSetNameLabelKey: roleSet.Name}
251		// 1. check if all podsets are delete for podGroupSize > 1
252		allPodSets := &orchestrationv1alpha1.PodSetList{}
253		if err := r.Client.List(ctx, allPodSets, client.InNamespace(roleSet.Namespace), selectorOpt); err != nil {
254			return false, err
255		} else if len(allPodSets.Items) != 0 {
256			// delete pods
257			for i := range allPodSets.Items {
258				if err = r.Client.Delete(ctx, &allPodSets.Items[i]); err != nil {
259					if apierrors.IsNotFound(err) {
260						continue
261					}
262					return false, err
263				}
264			}
265			// let's wait for next reconcile to move to next step, it helps make sure the podsets resources are cleaned up.
266			return false, nil
267		}
268	
269		// 2. check if all pods are deleted.
270		allPods := &v1.PodList{}
271		if err := r.Client.List(ctx, allPods, client.InNamespace(roleSet.Namespace), selectorOpt); err != nil {
272			return false, err
273		} else if len(allPods.Items) != 0 {
274			// delete pods
275			for i := range allPods.Items {
276				if err = r.Client.Delete(ctx, &allPods.Items[i]); err != nil {
277					if apierrors.IsNotFound(err) {
278						continue
279					}
280					return false, err
281				}
282			}
283			// let's wait for next reconcile to move to next step, it helps make sure the pod resources are cleaned up.
284			return false, nil
285		}
286	
287		// 3. check if pg is deleted
288		if err := utils.FinalizePodGroup(ctx, r.DynamicClient, r.Client, &schedv1alpha1.PodGroup{}, roleSet.Name, roleSet.Namespace); err != nil {
289			return false, err
290		}
291		if err := utils.FinalizePodGroup(ctx, r.DynamicClient, r.Client, &schedulerpluginsv1aplha1.PodGroup{}, roleSet.Name, roleSet.Namespace); err != nil {
292			return false, err
293		}
294		if err := utils.FinalizePodGroup(ctx, r.DynamicClient, r.Client, &volcanoschedv1beta1.PodGroup{}, roleSet.Name, roleSet.Namespace); err != nil {
295			return false, err
296		}
297	
298		// 3. remove finalizer
299		if controllerutil.ContainsFinalizer(roleSet, RoleSetFinalizer) {
300			if err := utils.Patch(ctx, r.Client, roleSet, patch.RemoveFinalizerPatch(roleSet, RoleSetFinalizer)); err != nil {
301				klog.Warningf("Failed to remove finalizer for roleSet %s/%s: %v", roleSet.Namespace, roleSet.Name, err)
302				return false, err
303			}
304		}
305		return true, nil
306	}
