36	// PodSetRoleSyncer implements RoleRollingSyncer using PodSets
37	// This follows the exact same patterns as StatefulRoleSyncer but operates on PodSets instead of Pods
38	type PodSetRoleSyncer struct {
39		cli client.Client
40		// To allow injection for testing.
41		computeHashFunc func(template *v1.PodTemplateSpec, collisionCount *int32) string
42		recorder        record.EventRecorder
43	}
44	
45	func (p *PodSetRoleSyncer) Scale(ctx context.Context, roleSet *orchestrationv1alpha1.RoleSet, role *orchestrationv1alpha1.RoleSpec) (bool, error) {
46		// Clean up orphan Pods left by the old StatefulRoleSyncer/StatelessRoleSyncer
47		// when podGroupSize was switched from <=1 to >1.
48		cleaned, err := cleanupOrphanPods(ctx, p.cli, roleSet, role)
49		if err != nil {
50			return cleaned, err
51		}
52		if cleaned {
53			klog.V(4).Infof("[PodSetRoleSyncer.Scale] cleaned orphan pods for roleset %s/%s role %s, waiting for next reconcile", roleSet.Namespace, roleSet.Name, role.Name)
54			return true, nil
55		}
56	
57		var podSetsToCreate, podSetsToDelete []*orchestrationv1alpha1.PodSet
58		allPodSets, err := getRolePodSets(ctx, p.cli, roleSet.Namespace, roleSet.Name, role.Name)
59		if err != nil {
60			return false, err
61		}
62		// delete podsets that are in terminated state
63		activePodSets, inactivePodSets := filterActivePodSets(allPodSets)
64		terminatingPodSets, terminatedPodSets := filterTerminatingPodSets(inactivePodSets)
65		podSetsToDelete = append(podSetsToDelete, terminatedPodSets...)
66	
67		// delete podsets that cannot find the corresponding slot
68		slots, toDelete := p.podSetSlotForRole(role, activePodSets)
69		podSetsToDelete = append(podSetsToDelete, toDelete...)
70		createBudget := int32(len(slots)) + MaxSurge(role) - int32(len(activePodSets)) - int32(len(terminatingPodSets))
71		// check podsets for each slot
72		for i := range slots {
73			if len(slots[i]) == 0 {
74				if createBudget <= 0 {
75					continue
76				}
77				podSet := p.createPodSetForRole(roleSet, role, &i)
78				podSetsToCreate = append(podSetsToCreate, podSet)
79				createBudget--
80			} else if len(slots[i]) > 1 {
81				readyPodSets, notReadyPodSets := filterReadyPodSets(slots[i])
82				roleTemplateHash := p.computeHashFunc(&role.Template, nil)
83				updatedReadyPodSets, outdatedReadyPodSets := filterUpdatedPodSets(readyPodSets, roleTemplateHash)
84				updatedNotReadyPodSets, outdatedNotReadyPodSets := filterUpdatedPodSets(notReadyPodSets, roleTemplateHash)
85				podSetsToDelete = append(podSetsToDelete, outdatedNotReadyPodSets...)
86				if len(updatedReadyPodSets) > 0 {
87					// only keep 1 updated ready podset for each slot
88					podSetsToDelete = append(podSetsToDelete, outdatedReadyPodSets...)
89					podSetsToDelete = append(podSetsToDelete, updatedNotReadyPodSets...)
90					if len(updatedReadyPodSets) > 1 {
91						podSetsToDelete = append(podSetsToDelete, updatedReadyPodSets[1:]...)
92					}
93				} else {
94					// keep 1 updated not ready podset & 1 outdated ready podset for each slot
95					if len(outdatedReadyPodSets) > 1 {
96						podSetsToDelete = append(podSetsToDelete, outdatedReadyPodSets[1:]...)
97					}
98					if len(updatedNotReadyPodSets) > 1 {
99						podSetsToDelete = append(podSetsToDelete, updatedNotReadyPodSets[1:]...)
100					}
101				}
102			}
103		}
104		if _, err = createPodSetsInBatch(ctx, p.cli, podSetsToCreate); err != nil {
105			return false, err
106		}
107		if _, err = deletePodSetsInBatch(ctx, p.cli, podSetsToDelete); err != nil {
108			return false, err
109		}
110		p.printLog(roleSet, role, podSetsToCreate, podSetsToDelete)
111		return len(podSetsToCreate) > 0 || len(podSetsToDelete) > 0, nil
112	}
113	
114	func (p *PodSetRoleSyncer) readySlotNum(role *orchestrationv1alpha1.RoleSpec, allPodSets []*orchestrationv1alpha1.PodSet) int {
115		activePodSets, _ := filterActivePodSets(allPodSets)
116		slots, _ := p.podSetSlotForRole(role, activePodSets)
117		var result int
118		for i := range slots {
119			ready, _ := filterReadyPodSets(slots[i])
120			if len(ready) >= 1 {
121				result++
122			}
123		}
124		return result
125	}
126	
127	func (p *PodSetRoleSyncer) updatedSlotNum(role *orchestrationv1alpha1.RoleSpec, allPodSets []*orchestrationv1alpha1.PodSet) (int32, int32, int32) {
128		activePodSets, _ := filterActivePodSets(allPodSets)
129		slots, _ := p.podSetSlotForRole(role, activePodSets)
130		currentHash := p.computeHashFunc(&role.Template, nil)
131	
132		updatedTotal := 0
133		updatedReadyTotal := 0
134		outdatedTotal := 0
135		for i := range slots {
136			// Consider the slot updated if it contains any PodSet with the new version
137			hasNewVersion := false
138			for _, podSet := range slots[i] {
139				if podSet.Labels[constants.RoleTemplateHashLabelKey] == currentHash {
140					hasNewVersion = true
141					break
142				}
143			}
144			if hasNewVersion {
145				updatedTotal++
146				if len(slots[i]) == 1 && isPodSetReady(slots[i][0]) {
147					updatedReadyTotal++
148				}
149			} else if len(slots[i]) > 0 {
150				outdatedTotal++
151			}
152		}
153		return int32(updatedTotal), int32(updatedReadyTotal), int32(outdatedTotal)
154	}
155	
156	func (p *PodSetRoleSyncer) Rollout(ctx context.Context, roleSet *orchestrationv1alpha1.RoleSet, role *orchestrationv1alpha1.RoleSpec) error {
157		var toCreate, toDelete []*orchestrationv1alpha1.PodSet
158		allPodSets, err := getRolePodSets(ctx, p.cli, roleSet.Namespace, roleSet.Name, role.Name)
159		if err != nil {
160			return err
161		}
162		expectedReplicas := getRoleReplicas(role)
163		activePodSets, _ := filterActivePodSets(allPodSets)
164		readySlotNum := p.readySlotNum(role, allPodSets)
165		deleteBudget := int32(readySlotNum) - expectedReplicas + MaxUnavailable(role)
166		createBudget := expectedReplicas + MaxSurge(role) - int32(len(allPodSets))
167		roleTemplateHash := p.computeHashFunc(&role.Template, nil)
168		klog.Infof("[PodSetRoleSyncer.Rollout] roleset %s/%s role %s expectedReplicas %d, deleteBudget %d, createBudget %d, template hash %s", roleSet.Namespace, roleSet.Name, role.Name, expectedReplicas, deleteBudget, createBudget, roleTemplateHash)
169		if roleUpdateStrategyTypeOrDefault(role) == orchestrationv1alpha1.InPlaceIfPossibleRoleUpdateStrategyType {
170			recordInPlaceFallback(p.recorder, roleSet, role, fmt.Sprintf("role %s uses PodSet and cannot be updated in place", role.Name))
171		}
172	
173		slots, _ := p.podSetSlotForRole(role, activePodSets)
174		for i := range slots {
175			if len(slots[i]) != 1 {
176				// wait for scale to handle this slot
177				continue
178			}
179			if slots[i][0].Labels[constants.RoleTemplateHashLabelKey] == roleTemplateHash {
180				continue
181			}
182			if !isPodSetReady(slots[i][0]) {
183				toDelete = append(toDelete, slots[i][0])
184				continue
185			}
186			if deleteBudget > 0 {
187				toDelete = append(toDelete, slots[i][0])
188				deleteBudget--
189			} else if createBudget > 0 {
190				podSet := p.createPodSetForRole(roleSet, role, &i)
191				toCreate = append(toCreate, podSet)
192				createBudget--
193			}
194		}
195		if _, err = createPodSetsInBatch(ctx, p.cli, toCreate); err != nil {
196			return err
197		}
198		if _, err = deletePodSetsInBatch(ctx, p.cli, toDelete); err != nil {
199			return err
200		}
201		p.printLog(roleSet, role, toCreate, toDelete)
202		return nil
203	}
204	
205	func (p *PodSetRoleSyncer) RolloutByStep(ctx context.Context, roleSet *orchestrationv1alpha1.RoleSet, role *orchestrationv1alpha1.RoleSpec, currentStep int32) error {
206		var toCreate, toDelete []*orchestrationv1alpha1.PodSet
207		allPodSets, err := getRolePodSets(ctx, p.cli, roleSet.Namespace, roleSet.Name, role.Name)
208		if err != nil {
209			return err
210		}
211	
212		expectedReplicas := getRoleReplicas(role)
213		expectedUpdatedReplicas := utils.MinInt32((MaxSurge(role)+MaxUnavailable(role))*currentStep, expectedReplicas)
214		activePodSets, _ := filterActivePodSets(allPodSets)
215		readySlotNum := p.readySlotNum(role, allPodSets)
216		deleteBudget := int32(readySlotNum) - expectedReplicas + MaxUnavailable(role)
217		createBudget := expectedReplicas + MaxSurge(role) - int32(len(allPodSets))
218		roleTemplateHash := p.computeHashFunc(&role.Template, nil)
219		klog.Infof("[PodSetRoleSyncer.RolloutByStep] Step %d: roleset %s/%s role %s expectedReplicas %d, deleteBudget %d, createBudget %d, template hash %s", currentStep, roleSet.Namespace, roleSet.Name, role.Name, expectedReplicas, deleteBudget, createBudget, roleTemplateHash)
220		if roleUpdateStrategyTypeOrDefault(role) == orchestrationv1alpha1.InPlaceIfPossibleRoleUpdateStrategyType {
221			recordInPlaceFallback(p.recorder, roleSet, role, fmt.Sprintf("role %s uses PodSet and cannot be updated in place", role.Name))
222		}
223	
224		updatedTotal, _, outdatedTotal := p.updatedSlotNum(role, allPodSets)
225	
226		// Constraints for this step:
227		// By the end of the current step, we aim to have (expectedReplicas - expectedUpdatedReplicas) outdated PodSets
228		// and expectedUpdatedReplicas updated PodSets.
229		// Therefore, the create and delete budgets must not exceed the difference between the current and expected states.
230		createBudget = utils.MinInt32(createBudget, expectedUpdatedReplicas-updatedTotal)
231		deleteBudget = utils.MinInt32(deleteBudget, outdatedTotal-expectedReplicas+expectedUpdatedReplicas)
232	
233		klog.Infof("[PodSetRoleSyncer.RolloutByStep] Step %d: roleset %s/%s role %s expectedUpdatedReplicas %d, updatedTotal %d, outdatedTotal %d, deleteBudget %d, createBudget %d",
234			currentStep, roleSet.Namespace, roleSet.Name, role.Name, expectedUpdatedReplicas, updatedTotal, outdatedTotal, deleteBudget, createBudget)
235		slots, _ := p.podSetSlotForRole(role, activePodSets)
236		for i := range slots {
237			if len(slots[i]) != 1 {
238				// wait for scale to handle this slot
239				continue
240			}
241			if slots[i][0].Labels[constants.RoleTemplateHashLabelKey] == roleTemplateHash {
242				continue
243			}
244			if !isPodSetReady(slots[i][0]) {
245				toDelete = append(toDelete, slots[i][0])
246				continue
247			}
248			if deleteBudget > 0 {
249				toDelete = append(toDelete, slots[i][0])
250				deleteBudget--
251			} else if createBudget > 0 {
252				podSet := p.createPodSetForRole(roleSet, role, &i)
253				toCreate = append(toCreate, podSet)
254				createBudget--
255			}
256		}
257		if _, err = createPodSetsInBatch(ctx, p.cli, toCreate); err != nil {
258			return err
259		}
260		if _, err = deletePodSetsInBatch(ctx, p.cli, toDelete); err != nil {
261			return err
262		}
263		p.printLog(roleSet, role, toCreate, toDelete)
264		return nil
265	}
266	
267	func (p *PodSetRoleSyncer) AllReady(ctx context.Context, roleSet *orchestrationv1alpha1.RoleSet, role *orchestrationv1alpha1.RoleSpec) (bool, error) {
268		allPodSets, err := getRolePodSets(ctx, p.cli, roleSet.Namespace, roleSet.Name, role.Name)
269		if err != nil {
270			return false, err
271		}
272		activePodSets, inactivePodSets := filterActivePodSets(allPodSets)
273		if len(inactivePodSets) != 0 {
274			return false, nil
275		}
276		ready, notReady := filterReadyPodSets(activePodSets)
277		if len(notReady) != 0 {
278			return false, nil
279		}
280		updated, outdated := filterUpdatedPodSets(ready, p.computeHashFunc(&role.Template, nil))
281		if len(outdated) != 0 {
282			return false, nil
283		}
284		slots, toDelete := p.podSetSlotForRole(role, updated)
285		if len(toDelete) != 0 {
286			return false, nil
287		}
288		for i := range slots {
289			if len(slots[i]) != 1 {
290				return false, nil
291			}
292		}
293		return true, nil
294	}
295	
296	func (p *PodSetRoleSyncer) CheckCurrentStep(ctx context.Context, roleSet *orchestrationv1alpha1.RoleSet, role *orchestrationv1alpha1.RoleSpec) (bool, int32, error) {
297		allPodSets, err := getRolePodSets(ctx, p.cli, roleSet.Namespace, roleSet.Name, role.Name)
298		if err != nil {
299			return false, 1, err
300		}
301	
302		stepLength := MaxSurge(role) + MaxUnavailable(role)
303		if stepLength < 1 {
304			stepLength = 1
305		}
306	
307		activePodSets, inactivePodSets := filterActivePodSets(allPodSets)
308		ready, notReady := filterReadyPodSets(activePodSets)
309		_, outdated := filterUpdatedPodSets(ready, p.computeHashFunc(&role.Template, nil))
310	
311		slotsActive, toDelete := p.podSetSlotForRole(role, activePodSets)
312		updatedSlots, readySlots, outdatedSlots := p.updatedSlotNum(role, allPodSets)
313		klog.Infof("[PodSetRoleSyncer.CheckCurrentStep] roleset %s/%s role %s updatedSlots: %d, updatedReadySlots: %d, outdatedSlots: %d",
314			roleSet.Namespace, roleSet.Name, role.Name, updatedSlots, readySlots, outdatedSlots)
315	
316		// First, determine the current step based on the number of ready slots already updated.
317		currentStep := (readySlots-1)/stepLength + int32(1)
318	
319		// Then, check whether we've entered the next step. This handles the following cases:
320		// 1. Critical boundary where the current step has just finished:
321		//    (len(toDelete) == 0 && int32(readySlots) == currentStep*stepLength && len(inactivePodSets) == 0 && len(notReady) == 0)
322		// 2. The current step has already finished earlier, but no new slot has become ready yet.
323		//    2.1 maxSurge is not allowed, so we terminate old slots first, leading to:
324		//        int32(outdatedSlots) < int32(len(slotsActive)) - stepLength * currentStep
325		//    2.2 maxUnavailable is not allowed, so we update new slots first, leading to:
326		//        int32(updatedSlots) > currentStep * stepLength
327	
328		// Q: Why not use updatedSlots and outdatedSlots directly to calculate the current step?
329		// A: To detect the critical boundary state precisely. The counts of updated and outdated slots
330		//    are not sufficient to determine this — we must rely on the number of *ready* slots.
331		if (len(toDelete) == 0 && readySlots == currentStep*stepLength && len(inactivePodSets) == 0 && len(notReady) == 0) ||
332			updatedSlots > currentStep*stepLength ||
333			outdatedSlots < int32(len(slotsActive))-stepLength*currentStep {
334			currentStep++
335		}
336	
337		allReady := len(toDelete) == 0 &&
338			len(inactivePodSets) == 0 &&
339			len(notReady) == 0 &&
340			len(outdated) == 0 &&
341			readySlots == int32(len(slotsActive))
342	
343		return allReady, currentStep, nil
344	}
345	
346	func (p *PodSetRoleSyncer) printLog(roleSet *orchestrationv1alpha1.RoleSet, role *orchestrationv1alpha1.RoleSpec, toCreate, toDelete []*orchestrationv1alpha1.PodSet) {
347		var creationNames, deletionNames []string
348		for _, podSet := range toCreate {
349			creationNames = append(creationNames, podSet.Name)
350		}
351		for _, podSet := range toDelete {
352			deletionNames = append(deletionNames, podSet.Name)
353		}
354		klog.Infof("roleset %s/%s role %s, toCreate %v, toDelete %v", roleSet.Namespace, roleSet.Name, role.Name, creationNames, deletionNames)
355	}
356	
357	func (p *PodSetRoleSyncer) podSetSlotForRole(role *orchestrationv1alpha1.RoleSpec, activePodSets []*orchestrationv1alpha1.PodSet) (slots [][]*orchestrationv1alpha1.PodSet, toDelete []*orchestrationv1alpha1.PodSet) {
358		expectedReplicas := getRoleReplicas(role)
359		slots = make([][]*orchestrationv1alpha1.PodSet, expectedReplicas)
360		for i := range activePodSets {
361			indexStr, ok := activePodSets[i].Labels[constants.RoleReplicaIndexLabelKey]
362			if !ok {
363				toDelete = append(toDelete, activePodSets[i])
364				continue
365			}
366			index, err := strconv.Atoi(indexStr)
367			if err != nil || index < 0 || index >= len(slots) {
368				toDelete = append(toDelete, activePodSets[i])
369				continue
370			}
371			slots[index] = append(slots[index], activePodSets[i])
372		}
373		return
374	}
375	
376	func (p *PodSetRoleSyncer) createPodSetForRole(roleSet *orchestrationv1alpha1.RoleSet, role *orchestrationv1alpha1.RoleSpec, roleIndex *int) *orchestrationv1alpha1.PodSet {
377		// Make a deep copy of the template first to avoid mutation issues
378		podTemplate := *role.Template.DeepCopy()
379		templateHash := p.computeHashFunc(&podTemplate, nil)
380		podSet := &orchestrationv1alpha1.PodSet{
381			ObjectMeta: metav1.ObjectMeta{
382				Namespace: roleSet.Namespace,
383				Labels: map[string]string{
384					// inject pod labels
385					constants.RoleSetNameLabelKey:      roleSet.Name,
386					constants.RoleNameLabelKey:         role.Name,
387					constants.RoleTemplateHashLabelKey: templateHash,
388					constants.StormServiceNameLabelKey: roleSet.Labels[constants.StormServiceNameLabelKey],
389				},
390				Annotations: map[string]string{
391					constants.RoleSetIndexAnnotationKey: roleSet.Annotations[constants.RoleSetIndexAnnotationKey],
392				},
393				OwnerReferences: []metav1.OwnerReference{
394					*metav1.NewControllerRef(roleSet, orchestrationv1alpha1.SchemeGroupVersion.WithKind(orchestrationv1alpha1.RoleSetKind)),
395				},
396			},
397			Spec: orchestrationv1alpha1.PodSetSpec{
398				PodGroupSize:       *role.PodGroupSize,
399				Template:           podTemplate,
400				Stateful:           role.Stateful,
401				SchedulingStrategy: role.SchedulingStrategy,
402			},
403		}
404	
405		if roleIndex != nil {
406			// add role template hash to pod name, to avoid pod name duplication during rollout
407			podSet.Name = utils.Shorten(fmt.Sprintf("%s-%s-%s-%d", roleSet.Name, role.Name, templateHash, *roleIndex), false, false)
408		} else {
409			podSet.GenerateName = utils.Shorten(fmt.Sprintf("%s-%s-", roleSet.Name, role.Name), false, true)
410		}
411	
412		// inject pod annotations
413		podSet.Annotations[constants.RoleSetIndexAnnotationKey] = roleSet.Annotations[constants.RoleSetIndexAnnotationKey]
414		if roleIndex != nil {
415			podSet.Annotations[constants.RoleReplicaIndexAnnotationKey] = strconv.Itoa(*roleIndex)
416			// inject to label as well for routing service discovery (some engines use label selector to find pods only)
417			podSet.Labels[constants.RoleReplicaIndexLabelKey] = strconv.Itoa(*roleIndex)
418		}
419	
420		if roleSet.Spec.SchedulingStrategy != nil {
421			if roleSet.Spec.SchedulingStrategy.CoschedulingSchedulingStrategy != nil {
422				podSet.Labels[constants.CoschedulingPodGroupNameLabelKey] = roleSet.Name
423			}
424			if roleSet.Spec.SchedulingStrategy.GodelSchedulingStrategy != nil {
425				podSet.Annotations[constants.GodelPodGroupNameAnnotationKey] = roleSet.Name
426				podSet.Labels[constants.GodelPodGroupNameAnnotationKey] = roleSet.Name
427			}
428			if roleSet.Spec.SchedulingStrategy.VolcanoSchedulingStrategy != nil {
429				podSet.Annotations[constants.VolcanoPodGroupNameAnnotationKey] = roleSet.Name
430				podSet.Labels[constants.VolcanoPodGroupNameAnnotationKey] = roleSet.Name
431			}
432		}
433		if role.SchedulingStrategy != nil { // note that roleSet.Spec.SchedulingStrategy and role.SchedulingStrategy should not be set concurrently
434			if role.SchedulingStrategy.CoschedulingSchedulingStrategy != nil {
435				podSet.Labels[constants.CoschedulingPodGroupNameLabelKey] = podSet.Name
436			}
437			if role.SchedulingStrategy.GodelSchedulingStrategy != nil {
438				podSet.Annotations[constants.GodelPodGroupNameAnnotationKey] = podSet.Name
439				podSet.Labels[constants.GodelPodGroupNameAnnotationKey] = podSet.Name
440			}
441			if role.SchedulingStrategy.VolcanoSchedulingStrategy != nil {
442				podSet.Annotations[constants.VolcanoPodGroupNameAnnotationKey] = podSet.Name
443				podSet.Labels[constants.VolcanoPodGroupNameAnnotationKey] = podSet.Name
444			}
445		}
446	
447		// inject container env
448		for i := range podSet.Spec.Template.Spec.Containers {
449			injectContainerEnvVars(
450				&podSet.Spec.Template.Spec.Containers[i],
451				roleSet,
452				role,
453				roleIndex,
454				templateHash,
455			)
456		}
457	
458		// inject topology co-location affinity if TopologyPolicy is specified
459		if roleSet.Spec.TopologyPolicy != nil {
460			injectTopologyAffinity(&podSet.Spec.Template.Spec, roleSet, role.Name, roleSet.Spec.TopologyPolicy)
461		}
462	
463		return podSet
464	}
465	
466	// getRolePodSets returns all PodSets for a specific role
467	func getRolePodSets(ctx context.Context, cli client.Client, namespace, roleSetName, roleName string) ([]*orchestrationv1alpha1.PodSet, error) {
468		podSetList := &orchestrationv1alpha1.PodSetList{}
469		err := cli.List(ctx, podSetList, client.InNamespace(namespace), client.MatchingLabels{
470			constants.RoleSetNameLabelKey: roleSetName,
471			constants.RoleNameLabelKey:    roleName,
472		})
473		if err != nil {
474			return nil, err
475		}
476	
477		result := make([]*orchestrationv1alpha1.PodSet, len(podSetList.Items))
478		for i := range podSetList.Items {
479			result[i] = &podSetList.Items[i]
480		}
481		return result, nil
482	}
483	
484	// filterActivePodSets separates active from inactive PodSets based on deletion timestamp
485	func filterActivePodSets(allPodSets []*orchestrationv1alpha1.PodSet) ([]*orchestrationv1alpha1.PodSet, []*orchestrationv1alpha1.PodSet) {
486		var active, inactive []*orchestrationv1alpha1.PodSet
487		for _, podSet := range allPodSets {
488			if isPodSetActive(podSet) {
489				active = append(active, podSet)
490			} else {
491				inactive = append(inactive, podSet)
492			}
493		}
494		return active, inactive
495	}
496	
497	// filterTerminatingPodSets separates terminating from terminated PodSets
498	func filterTerminatingPodSets(inactivePodSets []*orchestrationv1alpha1.PodSet) ([]*orchestrationv1alpha1.PodSet, []*orchestrationv1alpha1.PodSet) {
499		var terminating, terminated []*orchestrationv1alpha1.PodSet
500		for _, podSet := range inactivePodSets {
501			// PodSet is terminated if it has deletion timestamp and no finalizers
502			if podSet.DeletionTimestamp != nil && len(podSet.Finalizers) == 0 {
503				terminated = append(terminated, podSet)
504			} else if podSet.DeletionTimestamp != nil {
505				terminating = append(terminating, podSet)
506			}
507		}
508		return terminating, terminated
509	}
510	
511	// filterReadyPodSets separates ready from not ready PodSets
512	func filterReadyPodSets(podSets []*orchestrationv1alpha1.PodSet) ([]*orchestrationv1alpha1.PodSet, []*orchestrationv1alpha1.PodSet) {
513		var ready, notReady []*orchestrationv1alpha1.PodSet
514		for _, podSet := range podSets {
515			if isPodSetReady(podSet) {
516				ready = append(ready, podSet)
517			} else {
518				notReady = append(notReady, podSet)
519			}
520		}
521		return ready, notReady
522	}
523	
524	// filterUpdatedPodSets separates updated from outdated PodSets based on template hash
525	func filterUpdatedPodSets(podSets []*orchestrationv1alpha1.PodSet, templateHash string) ([]*orchestrationv1alpha1.PodSet, []*orchestrationv1alpha1.PodSet) {
526		var updated, outdated []*orchestrationv1alpha1.PodSet
527		for _, podSet := range podSets {
528			if podSet.Labels[constants.RoleTemplateHashLabelKey] == templateHash {
529				updated = append(updated, podSet)
530			} else {
531				outdated = append(outdated, podSet)
532			}
533		}
534		return updated, outdated
535	}
536	
537	// isPodSetReady checks if a PodSet is ready
538	func isPodSetReady(podSet *orchestrationv1alpha1.PodSet) bool {
539		return podSet.Status.Phase == orchestrationv1alpha1.PodSetPhaseReady
540	}
541	
542	// isPodSetActive checks if a PodSet is active
543	func isPodSetActive(podSet *orchestrationv1alpha1.PodSet) bool {
544		return podSet.DeletionTimestamp == nil && podSet.Status.Phase != orchestrationv1alpha1.PodSetPhaseFailed
545	}
546	
547	// createPodSetsInBatch creates multiple PodSets
548	func createPodSetsInBatch(ctx context.Context, cli client.Client, podSets []*orchestrationv1alpha1.PodSet) (int, error) {
549		for _, podSet := range podSets {
550			if err := cli.Create(ctx, podSet); err != nil {
551				return 0, err
552			}
553		}
554		return len(podSets), nil
555	}
556	
557	// deletePodSetsInBatch deletes multiple PodSets
558	func deletePodSetsInBatch(ctx context.Context, cli client.Client, podSets []*orchestrationv1alpha1.PodSet) (int, error) {
559		for _, podSet := range podSets {
560			if err := cli.Delete(ctx, podSet); err != nil && !apierrors.IsNotFound(err) {
561				return 0, err
562			}
563		}
564		return len(podSets), nil
565	}
