37	type RoleRollingSyncer interface {
38		Scale(ctx context.Context, roleSet *orchestrationv1alpha1.RoleSet, role *orchestrationv1alpha1.RoleSpec) (bool, error)
39		Rollout(ctx context.Context, roleSet *orchestrationv1alpha1.RoleSet, role *orchestrationv1alpha1.RoleSpec) error
40		RolloutByStep(ctx context.Context, roleSet *orchestrationv1alpha1.RoleSet, role *orchestrationv1alpha1.RoleSpec, currentStep int32) error
41		AllReady(ctx context.Context, roleSet *orchestrationv1alpha1.RoleSet, role *orchestrationv1alpha1.RoleSpec) (bool, error)
42		CheckCurrentStep(ctx context.Context, roleSet *orchestrationv1alpha1.RoleSet, role *orchestrationv1alpha1.RoleSpec) (bool, int32, error)
43	}
44	
45	type StatefulRoleSyncer struct {
46		cli client.Client
47		// To allow injection for testing.
48		computeHashFunc func(template *v1.PodTemplateSpec, collisionCount *int32) string
49		recorder        record.EventRecorder
50	}
