52	func (s *StatefulRoleSyncer) Scale(ctx context.Context, roleSet *orchestrationv1alpha1.RoleSet, role *orchestrationv1alpha1.RoleSpec) (bool, error) {
53		// Clean up orphan PodSets left by the old PodSetRoleSyncer
54		// when podGroupSize was switched from >1 to <=1.
55		cleaned, err := cleanupOrphanPodSets(ctx, s.cli, roleSet, role)
56		if err != nil {
57			return cleaned, err
58		}
59		if cleaned {
60			klog.V(4).Infof("[StatefulRoleSyncer.Scale] cleaned orphan podsets for roleset %s/%s role %s, waiting for next reconcile", roleSet.Namespace, roleSet.Name, role.Name)
61			return true, nil
62		}
63	
64		var podsToCreate, podsToDelete []*v1.Pod
65		allPods, err := getRolePods(ctx, s.cli, roleSet.Namespace, roleSet.Name, role.Name)
66		if err != nil {
67			return false, err
68		}
69		// delete pods that are in terminated state
70		activePods, inactivePods := filterActivePods(allPods)
71		terminatingPods, terminatedPods := filterTerminatingPods(inactivePods)
72		podsToDelete = append(podsToDelete, terminatedPods...)
73	
74		// delete pods that cannot find the corresponding slot
75		slots, toDelete := s.podSlotForRole(role, activePods)
76		podsToDelete = append(podsToDelete, toDelete...)
77		createBudget := int32(len(slots)) + MaxSurge(role) - int32(len(activePods)) - int32(len(terminatingPods))
78		// check pods for each slot
79		for i := range slots {
80			if len(slots[i]) == 0 {
81				if createBudget <= 0 {
82					continue
83				}
84				pod, err := ctrlutil.GetPodFromTemplate(&role.Template, roleSet, metav1.NewControllerRef(roleSet, orchestrationv1alpha1.SchemeGroupVersion.WithKind(orchestrationv1alpha1.RoleSetKind)))
85				if err != nil {
86					return false, err
87				}
88				renderStormServicePod(roleSet, role, pod, &i)
89				podsToCreate = append(podsToCreate, pod)
90				createBudget--
91			} else if len(slots[i]) > 1 {
92				readyPods, notReadyPods := filterReadyPods(slots[i])
93				roleTemplateHash := s.computeHashFunc(&role.Template, nil)
94				updatedReadyPods, outdatedReadyPods := filterUpdatedPods(readyPods, roleTemplateHash)
95				updatedNotReadyPods, outdatedNotReadyPods := filterUpdatedPods(notReadyPods, roleTemplateHash)
96				podsToDelete = append(podsToDelete, outdatedNotReadyPods...)
97				if len(updatedReadyPods) > 0 {
98					// only keep 1 updated ready pod for each slot
99					podsToDelete = append(podsToDelete, outdatedReadyPods...)
100					podsToDelete = append(podsToDelete, updatedNotReadyPods...)
101					if len(updatedReadyPods) > 1 {
102						podsToDelete = append(podsToDelete, updatedReadyPods[1:]...)
103					}
104				} else {
105					// keep 1 updated not ready pod & 1 outdated ready pod for each slot
106					if len(outdatedReadyPods) > 1 {
107						podsToDelete = append(podsToDelete, outdatedReadyPods[1:]...)
108					}
109					if len(updatedNotReadyPods) > 1 {
110						podsToDelete = append(podsToDelete, updatedNotReadyPods[1:]...)
111					}
112				}
113			}
114		}
115		if _, err = createPodsInBatch(ctx, s.cli, podsToCreate); err != nil {
116			return false, err
117		}
118		if _, err = deletePodsInBatch(ctx, s.cli, podsToDelete); err != nil {
119			return false, err
120		}
121		s.printLog(roleSet, role, podsToCreate, podsToDelete)
122		return len(podsToCreate) > 0 || len(podsToDelete) > 0, nil
123	}
124	
125	func (s *StatefulRoleSyncer) readySlotNum(role *orchestrationv1alpha1.RoleSpec, allPods []*v1.Pod) int {
126		activePods, _ := filterActivePods(allPods)
127		slots, _ := s.podSlotForRole(role, activePods)
128		var result int
129		for i := range slots {
130			ready, _ := filterReadyPods(slots[i])
131			if len(ready) >= 1 {
132				result++
133			}
134		}
135		return result
136	}
137	
138	func (s *StatefulRoleSyncer) updatedSlotNum(role *orchestrationv1alpha1.RoleSpec, allPods []*v1.Pod) (int32, int32, int32) {
139		activePods, _ := filterActivePods(allPods)
140		slots, _ := s.podSlotForRole(role, activePods)
141		currentHash := s.computeHashFunc(&role.Template, nil)
142	
143		updatedTotal := 0
144		updatedReadyTotal := 0
145		outdatedTotal := 0
146		for i := range slots {
147			// Consider the slot updated if it contains any Pod with the new version
148			hasNewVersion := false
149			for _, pod := range slots[i] {
150				if pod.Labels[constants.RoleTemplateHashLabelKey] == currentHash {
151					hasNewVersion = true
152					break
153				}
154			}
155			if hasNewVersion {
156				updatedTotal++
157				if len(slots[i]) == 1 && podutil.IsPodReady(slots[i][0]) {
158					updatedReadyTotal++
159				}
160			} else if len(slots[i]) > 0 {
161				outdatedTotal++
162			}
163		}
164		return int32(updatedTotal), int32(updatedReadyTotal), int32(outdatedTotal)
165	}
166	
167	func (s *StatefulRoleSyncer) Rollout(ctx context.Context, roleSet *orchestrationv1alpha1.RoleSet, role *orchestrationv1alpha1.RoleSpec) error {
168		var toCreate, toDelete []*v1.Pod
169		allPods, err := getRolePods(ctx, s.cli, roleSet.Namespace, roleSet.Name, role.Name)
170		if err != nil {
171			return err
172		}
173		expectedReplicas := getRoleReplicas(role)
174		activePods, _ := filterActivePods(allPods)
175		readySlotNum := s.readySlotNum(role, allPods)
176		deleteBudget := int32(readySlotNum) - expectedReplicas + MaxUnavailable(role)
177		createBudget := expectedReplicas + MaxSurge(role) - int32(len(allPods))
178		roleTemplateHash := s.computeHashFunc(&role.Template, nil)
179		klog.Infof("[StatefulRoleSyncer.Rollout] roleset %s/%s role %s expectedReplicas %d, deleteBudget %d, createBudget %d, template hash %s", roleSet.Namespace, roleSet.Name, role.Name, expectedReplicas, deleteBudget, createBudget, roleTemplateHash)
180	
181		slots, _ := s.podSlotForRole(role, activePods)
182		var outdatedPods []*v1.Pod
183		for i := range slots {
184			if len(slots[i]) != 1 {
185				continue
186			}
187			if slots[i][0].Labels[constants.RoleTemplateHashLabelKey] != roleTemplateHash {
188				outdatedPods = append(outdatedPods, slots[i][0])
189			}
190		}
191		strategy := roleUpdateStrategyTypeOrDefault(role)
192		if strategy == orchestrationv1alpha1.InPlaceIfPossibleRoleUpdateStrategyType {
193			possible, reason, err := canRolloutPodsInPlace(roleSet, role, outdatedPods, roleTemplateHash, s.computeHashFunc)
194			if err != nil {
195				return err
196			}
197			if possible {
198				return rolloutPodsInPlace(ctx, s.cli, roleSet, role, outdatedPods, roleTemplateHash, deleteBudget, s.computeHashFunc, s.recorder)
199			}
200			recordInPlaceFallback(s.recorder, roleSet, role, reason)
201		}
202		for i := range slots {
203			if len(slots[i]) != 1 {
204				// wait for scale to handle this slot
205				continue
206			}
207			if slots[i][0].Labels[constants.RoleTemplateHashLabelKey] == roleTemplateHash {
208				continue
209			}
210			if !podutil.IsPodReady(slots[i][0]) {
211				toDelete = append(toDelete, slots[i][0])
212				continue
213			}
214			if deleteBudget > 0 {
215				toDelete = append(toDelete, slots[i][0])
216				deleteBudget--
217			} else if createBudget > 0 {
218				pod, err := ctrlutil.GetPodFromTemplate(&role.Template, roleSet, metav1.NewControllerRef(roleSet, orchestrationv1alpha1.SchemeGroupVersion.WithKind(orchestrationv1alpha1.RoleSetKind)))
219				if err != nil {
220					return err
221				}
222				renderStormServicePod(roleSet, role, pod, &i)
223				toCreate = append(toCreate, pod)
224				createBudget--
225			}
226		}
227		if _, err = createPodsInBatch(ctx, s.cli, toCreate); err != nil {
228			return err
229		}
230		if _, err = deletePodsInBatch(ctx, s.cli, toDelete); err != nil {
231			return err
232		}
233		s.printLog(roleSet, role, toCreate, toDelete)
234		return nil
235	}
236	
237	func (s *StatefulRoleSyncer) RolloutByStep(ctx context.Context, roleSet *orchestrationv1alpha1.RoleSet, role *orchestrationv1alpha1.RoleSpec, currentStep int32) error {
238		var toCreate, toDelete []*v1.Pod
239		allPods, err := getRolePods(ctx, s.cli, roleSet.Namespace, roleSet.Name, role.Name)
240		if err != nil {
241			return err
242		}
243	
244		expectedReplicas := getRoleReplicas(role)
245		expectedUpdatedReplicas := utils.MinInt32((MaxSurge(role)+MaxUnavailable(role))*currentStep, expectedReplicas)
246		activePods, _ := filterActivePods(allPods)
247		readySlotNum := s.readySlotNum(role, allPods)
248		deleteBudget := int32(readySlotNum) - expectedReplicas + MaxUnavailable(role)
249		createBudget := expectedReplicas + MaxSurge(role) - int32(len(allPods))
250		roleTemplateHash := s.computeHashFunc(&role.Template, nil)
251		klog.Infof("[StatefulRoleSyncer.RolloutByStep] Step %d: roleset %s/%s role %s expectedReplicas %d, deleteBudget %d, createBudget %d, template hash %s", currentStep, roleSet.Namespace, roleSet.Name, role.Name, expectedReplicas, deleteBudget, createBudget, roleTemplateHash)
252	
253		updatedTotal, _, outdatedTotal := s.updatedSlotNum(role, allPods)
254	
255		// Constraints for this step:
256		// By the end of the current step, we aim to have (expectedReplicas - expectedUpdatedReplicas) outdated Pods
257		// and expectedUpdatedReplicas updated Pods.
258		// Therefore, the create and delete budgets must not exceed the difference between the current and expected states.
259		createBudget = utils.MinInt32(createBudget, expectedUpdatedReplicas-updatedTotal)
260		deleteBudget = utils.MinInt32(deleteBudget, outdatedTotal-expectedReplicas+expectedUpdatedReplicas)
261	
262		klog.Infof("[StatefulRoleSyncer.RolloutByStep] Step %d: roleset %s/%s role %s expectedUpdatedReplicas %d, updatedTotal %d, outdatedTotal %d, deleteBudget %d, createBudget %d",
263			currentStep, roleSet.Namespace, roleSet.Name, role.Name, expectedUpdatedReplicas, updatedTotal, outdatedTotal, deleteBudget, createBudget)
264		slots, _ := s.podSlotForRole(role, activePods)
265		strategy := roleUpdateStrategyTypeOrDefault(role)
266		if strategy == orchestrationv1alpha1.InPlaceIfPossibleRoleUpdateStrategyType {
267			var outdatedPods []*v1.Pod
268			for i := range slots {
269				if len(slots[i]) == 1 && slots[i][0].Labels[constants.RoleTemplateHashLabelKey] != roleTemplateHash {
270					outdatedPods = append(outdatedPods, slots[i][0])
271				}
272			}
273			possible, reason, err := canRolloutPodsInPlace(roleSet, role, outdatedPods, roleTemplateHash, s.computeHashFunc)
274			if err != nil {
275				return err
276			}
277			if possible {
278				selected := selectInPlaceOutdatedPodsForStep(outdatedPods, roleTemplateHash, expectedUpdatedReplicas-updatedTotal)
279				return rolloutPodsInPlace(ctx, s.cli, roleSet, role, selected, roleTemplateHash, deleteBudget, s.computeHashFunc, s.recorder)
280			}
281			recordInPlaceFallback(s.recorder, roleSet, role, reason)
282		}
283		for i := range slots {
284			if len(slots[i]) != 1 {
285				// wait for scale to handle this slot
286				continue
287			}
288			if slots[i][0].Labels[constants.RoleTemplateHashLabelKey] == roleTemplateHash {
289				continue
290			}
291			if !podutil.IsPodReady(slots[i][0]) {
292				toDelete = append(toDelete, slots[i][0])
293				continue
294			}
295			if deleteBudget > 0 {
296				toDelete = append(toDelete, slots[i][0])
297				deleteBudget--
298			} else if createBudget > 0 {
299				pod, err := ctrlutil.GetPodFromTemplate(&role.Template, roleSet, metav1.NewControllerRef(roleSet, orchestrationv1alpha1.SchemeGroupVersion.WithKind(orchestrationv1alpha1.RoleSetKind)))
300				if err != nil {
301					return err
302				}
303				renderStormServicePod(roleSet, role, pod, &i)
304				toCreate = append(toCreate, pod)
305				createBudget--
306			}
307		}
308		if _, err = createPodsInBatch(ctx, s.cli, toCreate); err != nil {
309			return err
310		}
311		if _, err = deletePodsInBatch(ctx, s.cli, toDelete); err != nil {
312			return err
313		}
314		s.printLog(roleSet, role, toCreate, toDelete)
315		return nil
316	}
317	
318	func (s *StatefulRoleSyncer) AllReady(ctx context.Context, roleSet *orchestrationv1alpha1.RoleSet, role *orchestrationv1alpha1.RoleSpec) (bool, error) {
319		allPods, err := getRolePods(ctx, s.cli, roleSet.Namespace, roleSet.Name, role.Name)
320		if err != nil {
321			return false, err
322		}
323		activePods, inactivePods := filterActivePods(allPods)
324		if len(inactivePods) != 0 {
325			return false, nil
326		}
327		ready, notReady := filterReadyPods(activePods)
328		if len(notReady) != 0 {
329			return false, nil
330		}
331		updated, outdated := filterUpdatedPods(ready, s.computeHashFunc(&role.Template, nil))
332		if len(outdated) != 0 {
333			return false, nil
334		}
335		slots, toDelete := s.podSlotForRole(role, updated)
336		if len(toDelete) != 0 {
337			return false, nil
338		}
339		for i := range slots {
340			if len(slots[i]) != 1 {
341				return false, nil
342			}
343		}
344		return true, nil
345	}
346	
347	func (s *StatefulRoleSyncer) CheckCurrentStep(ctx context.Context, roleSet *orchestrationv1alpha1.RoleSet, role *orchestrationv1alpha1.RoleSpec) (bool, int32, error) {
348		allPods, err := getRolePods(ctx, s.cli, roleSet.Namespace, roleSet.Name, role.Name)
349		if err != nil {
350			return false, 1, err
351		}
352	
353		stepLength := MaxSurge(role) + MaxUnavailable(role)
354		if stepLength < 1 {
355			stepLength = 1
356		}
357	
358		activePods, inactivePods := filterActivePods(allPods)
359		ready, notReady := filterReadyPods(activePods)
360		_, outdated := filterUpdatedPods(ready, s.computeHashFunc(&role.Template, nil))
361	
362		slotsActive, toDelete := s.podSlotForRole(role, activePods)
363		updatedSlots, readySlots, outdatedSlots := s.updatedSlotNum(role, activePods)
364		klog.Infof("[StatefulRoleSyncer.CheckCurrentStep] roleset %s/%s role %s updatedSlots: %d, updatedReadySlots: %d, outdatedSlots: %d",
365			roleSet.Namespace, roleSet.Name, role.Name, updatedSlots, readySlots, outdatedSlots)
366	
367		// First, determine the current step based on the number of ready slots already updated.
368		currentStep := (readySlots-1)/stepLength + int32(1)
369	
370		// Then, check whether we've entered the next step. This handles the following cases:
371		// 1. Critical boundary where the current step has just finished:
372		//    (len(toDelete) == 0 && int32(readySlots) == currentStep*stepLength && len(inactivePods) == 0 && len(notReady) == 0)
373		// 2. The current step has already finished earlier, but no new slot has become ready yet.
374		//    2.1 maxSurge is not allowed, so we terminate old slots first, leading to:
375		//        int32(outdatedSlots) < int32(len(slotsActive)) - stepLength * currentStep
376		//    2.2 maxUnavailable is not allowed, so we update new slots first, leading to:
377		//        int32(updatedSlots) > currentStep * stepLength
378	
379		// Q: Why not use updatedSlots and outdatedSlots directly to calculate the current step?
380		// A: To detect the critical boundary state precisely. The counts of updated and outdated slots
381		//    are not sufficient to determine this — we must rely on the number of *ready* slots.
382		if (len(toDelete) == 0 && readySlots == currentStep*stepLength && len(inactivePods) == 0 && len(notReady) == 0) ||
383			updatedSlots > currentStep*stepLength ||
384			outdatedSlots < int32(len(slotsActive))-stepLength*currentStep {
385			currentStep++
386		}
387	
388		allReady := len(toDelete) == 0 &&
389			len(inactivePods) == 0 &&
390			len(notReady) == 0 &&
391			len(outdated) == 0 &&
392			readySlots == int32(len(slotsActive))
393	
394		return allReady, currentStep, nil
395	}
