408	func (s *StatefulRoleSyncer) podSlotForRole(role *orchestrationv1alpha1.RoleSpec, activePods []*v1.Pod) (slots [][]*v1.Pod, toDelete []*v1.Pod) {
409		expectedReplicas := getRoleReplicas(role)
410		slots = make([][]*v1.Pod, expectedReplicas)
411		for i := range activePods {
412			indexStr, ok := activePods[i].Annotations[constants.RoleReplicaIndexAnnotationKey]
413			if !ok {
414				toDelete = append(toDelete, activePods[i])
415				continue
416			}
417			index, err := strconv.Atoi(indexStr)
418			if err != nil || index < 0 || index >= len(slots) {
419				toDelete = append(toDelete, activePods[i])
420				continue
421			}
422			slots[index] = append(slots[index], activePods[i])
423		}
424		return
425	}
