434	func (s *StatelessRoleSyncer) Scale(ctx context.Context, roleSet *orchestrationv1alpha1.RoleSet, role *orchestrationv1alpha1.RoleSpec) (bool, error) {
435		// Clean up orphan PodSets left by the old PodSetRoleSyncer
436		// when podGroupSize was switched from >1 to <=1.
437		cleaned, err := cleanupOrphanPodSets(ctx, s.cli, roleSet, role)
438		if err != nil {
439			return cleaned, err
440		}
441		if cleaned {
442			klog.V(4).Infof("[StatelessRoleSyncer.Scale] cleaned orphan podsets for roleset %s/%s role %s, waiting for next reconcile", roleSet.Namespace, roleSet.Name, role.Name)
443			return true, nil
444		}
445	
446		var toCreate, toDelete []*v1.Pod
447		allPods, err := getRolePods(ctx, s.cli, roleSet.Namespace, roleSet.Name, role.Name)
448		if err != nil {
449			return false, err
450		}
451		// delete pods that are in terminated state
452		activePods, inactivePods := filterActivePods(allPods)
453		_, terminatedPods := filterTerminatingPods(inactivePods)
454		toDelete = append(toDelete, terminatedPods...)
455	
456		// reconcile active pods to meet expected replicas
457		expectedReplicas := getRoleReplicas(role)
458		diff := len(activePods) - int(expectedReplicas)
459		if diff > 0 {
460			sortPodsByTemplateHash(activePods, s.computeHashFunc(&role.Template, nil))
461			readyPods, _ := filterReadyPods(activePods)
462			readyCount := len(readyPods)
463			minAvailable := expectedReplicas - MaxUnavailable(role)
464			klog.Infof("[StatelessRoleSyncer.Scale] roleset %s/%s role %s readyPods %d, expectedReplicas %d, minAvailable %d, deleting pods...", roleSet.Namespace, roleSet.Name, role.Name, len(readyPods), expectedReplicas, minAvailable)
465			for i := 0; i < len(activePods); i++ {
466				if diff == 0 {
467					break
468				}
469				if readyCount <= int(minAvailable) {
470					break
471				}
472				toDelete = append(toDelete, activePods[i])
473				if podutil.IsPodReady(activePods[i]) {
474					readyCount--
475				}
476				diff--
477			}
478			klog.Infof("[StatelessRoleSyncer.Scale] roleset %s/%s role %s toDelete %d pods", roleSet.Namespace, roleSet.Name, role.Name, len(toDelete))
479		} else if diff < 0 {
480			klog.Infof("[StatelessRoleSyncer.Scale] roleset %s/%s role %s activePods %d, expectedReplicas %d, creating pods...", roleSet.Namespace, roleSet.Name, role.Name, len(activePods), expectedReplicas)
481			terminatingPods, _ := filterTerminatingPods(allPods)
482			terminatingPodCount := len(terminatingPods)
483			// take pods that are in terminating state into account
484			createBudget := utils.MinInt32(int32(-diff), expectedReplicas+MaxSurge(role)-int32(len(activePods))-int32(terminatingPodCount))
485			for i := int32(0); i < createBudget; i++ {
486				pod, err := ctrlutil.GetPodFromTemplate(&role.Template, roleSet, metav1.NewControllerRef(roleSet, orchestrationv1alpha1.SchemeGroupVersion.WithKind(orchestrationv1alpha1.RoleSetKind)))
487				if err != nil {
488					return false, err
489				}
490				renderStormServicePod(roleSet, role, pod, nil)
491				toCreate = append(toCreate, pod)
492			}
493			klog.Infof("[StatelessRoleSyncer.Scale] roleset %s/%s role %s toCreate %d pods", roleSet.Namespace, roleSet.Name, role.Name, len(toCreate))
494		}
495		if _, err = createPodsInBatch(ctx, s.cli, toCreate); err != nil {
496			return false, err
497		}
498		if _, err = deletePodsInBatch(ctx, s.cli, toDelete); err != nil {
499			return false, err
500		}
501		return len(toCreate) > 0 || len(toDelete) > 0, nil
502	}
