504	func (s *StatelessRoleSyncer) Rollout(ctx context.Context, roleSet *orchestrationv1alpha1.RoleSet, role *orchestrationv1alpha1.RoleSpec) error {
505		var toCreate, toDelete []*v1.Pod
506		allPods, err := getRolePods(ctx, s.cli, roleSet.Namespace, roleSet.Name, role.Name)
507		if err != nil {
508			return err
509		}
510		activePods, _ := filterActivePods(allPods)
511		expectedReplicas := getRoleReplicas(role)
512		roleTemplateHash := s.computeHashFunc(&role.Template, nil)
513		updated, outdated := filterUpdatedPods(activePods, roleTemplateHash)
514		klog.Infof("[StatelessRoleSyncer.Rollout] roleset %s/%s role %s updated %d, outdated %d, expectedReplicas %d, hash %s", roleSet.Namespace, roleSet.Name, role.Name, len(updated), len(outdated), expectedReplicas, roleTemplateHash)
515		ready, _ := filterReadyPods(activePods)
516		deleteBudget := int32(len(ready)) - expectedReplicas + MaxUnavailable(role)
517		strategy := roleUpdateStrategyTypeOrDefault(role)
518		if strategy == orchestrationv1alpha1.InPlaceIfPossibleRoleUpdateStrategyType {
519			possible, reason, err := canRolloutPodsInPlace(roleSet, role, outdated, roleTemplateHash, s.computeHashFunc)
520			if err != nil {
521				return err
522			}
523			if possible {
524				if err := s.rolloutInPlace(ctx, roleSet, role, outdated, roleTemplateHash, deleteBudget); err != nil {
525					return err
526				}
527				return nil
528			}
529			recordInPlaceFallback(s.recorder, roleSet, role, reason)
530		}
531		sortPodsByActive(outdated)
532		// 1. delete outdated pods
533		for i := 0; i < len(outdated); i++ {
534			if podutil.IsPodReady(outdated[i]) {
535				if deleteBudget <= 0 {
536					break
537				}
538				deleteBudget--
539			}
540			toDelete = append(toDelete, outdated[i])
541		}
542		// 2. created new pods
543		terminatingPods, _ := filterTerminatingPods(allPods)
544		terminatingPodCount := len(terminatingPods)
545		// take terminating pods into account
546		createBudget := utils.MinInt32(expectedReplicas+MaxSurge(role)-int32(len(activePods))-int32(terminatingPodCount), expectedReplicas-int32(len(updated)))
547		for i := int32(0); i < createBudget; i++ {
548			pod, err := ctrlutil.GetPodFromTemplate(&role.Template, roleSet, metav1.NewControllerRef(roleSet, orchestrationv1alpha1.SchemeGroupVersion.WithKind(orchestrationv1alpha1.RoleSetKind)))
549			if err != nil {
550				return err
551			}
552			renderStormServicePod(roleSet, role, pod, nil)
553			toCreate = append(toCreate, pod)
554		}
555		klog.Infof("[StatelessRoleSyncer.Rollout] roleset %s/%s outdated %d, expectedReplicas %d, deleteBudget %d, createBudget %d, allPods %d, toDelete %d, toCreate %d", roleSet.Namespace, roleSet.Name, len(outdated), expectedReplicas, deleteBudget, createBudget, len(allPods), len(toDelete), len(toCreate))
556		if _, err = createPodsInBatch(ctx, s.cli, toCreate); err != nil {
557			return err
558		}
559		if _, err = deletePodsInBatch(ctx, s.cli, toDelete); err != nil {
560			return err
561		}
562		return nil
563	}
