565	func (s *StatelessRoleSyncer) rolloutInPlace(ctx context.Context, roleSet *orchestrationv1alpha1.RoleSet, role *orchestrationv1alpha1.RoleSpec, outdated []*v1.Pod, roleTemplateHash string, unavailableBudget int32) error {
566		return rolloutPodsInPlace(ctx, s.cli, roleSet, role, outdated, roleTemplateHash, unavailableBudget, s.computeHashFunc, s.recorder)
567	}
568	
569	func rolloutPodsInPlace(ctx context.Context, cli client.Client, roleSet *orchestrationv1alpha1.RoleSet, role *orchestrationv1alpha1.RoleSpec, outdated []*v1.Pod, roleTemplateHash string, unavailableBudget int32, hashFunc func(*v1.PodTemplateSpec, *int32) string, recorder record.EventRecorder) error {
570		sortPodsByActive(outdated)
571		var candidates []*v1.Pod
572		// First settle pods that were patched in a previous reconcile. A ready pod
573		// with the target annotation still consumes disruption budget until kubelet
574		// reports the desired runtime image and the hash label is promoted.
575		for _, pod := range outdated {
576			hadTargetAnnotation := pod.Annotations[constants.RoleInPlaceUpdateTargetHashAnnotationKey] == roleTemplateHash
577			if completed, err := markInPlaceUpdateComplete(ctx, cli, roleSet, role, pod, roleTemplateHash); err != nil {
578				return err
579			} else if completed {
580				if hadTargetAnnotation {
581					recordInPlaceUpdateCompleted(recorder, roleSet, role, pod)
582				}
583				continue
584			}
585			if pod.Annotations[constants.RoleInPlaceUpdateTargetHashAnnotationKey] == roleTemplateHash {
586				if podutil.IsPodReady(pod) {
587					unavailableBudget--
588				}
589				continue
590			}
591			candidates = append(candidates, pod)
592		}
593	
594		// Then patch new candidates with any remaining budget.
595		for _, pod := range candidates {
596	
597			eligible, reason, err := canInPlaceUpdatePod(roleSet, role, pod, hashFunc)
598			if err != nil {
599				return err
600			}
601			if !eligible {
602				return fmt.Errorf("role %s pod %s is not eligible for in-place update: %s", role.Name, pod.Name, reason)
603			}
604			if podutil.IsPodReady(pod) {
605				if unavailableBudget <= 0 {
606					continue
607				}
608				unavailableBudget--
609			}
610			if changed, err := patchPodImagesForInPlaceUpdate(ctx, cli, pod, role, roleTemplateHash); err != nil {
611				return err
612			} else if changed {
613				recordInPlaceUpdateStarted(recorder, roleSet, role, pod)
614			}
615		}
616		return nil
617	}
618	
619	func canRolloutPodsInPlace(roleSet *orchestrationv1alpha1.RoleSet, role *orchestrationv1alpha1.RoleSpec, outdated []*v1.Pod, roleTemplateHash string, hashFunc func(*v1.PodTemplateSpec, *int32) string) (bool, string, error) {
620		for _, pod := range outdated {
621			if pod.Annotations[constants.RoleInPlaceUpdateTargetHashAnnotationKey] == roleTemplateHash {
622				continue
623			}
624			eligible, reason, err := canInPlaceUpdatePod(roleSet, role, pod, hashFunc)
625			if err != nil {
626				return false, "", err
627			}
628			if !eligible {
629				return false, fmt.Sprintf("role %s pod %s cannot be updated in place: %s", role.Name, pod.Name, reason), nil
630			}
631		}
632		return true, "", nil
633	}
634	
635	func recordInPlaceFallback(recorder record.EventRecorder, roleSet *orchestrationv1alpha1.RoleSet, role *orchestrationv1alpha1.RoleSpec, reason string) {
636		if recorder == nil {
637			return
638		}
639		if reason == "" {
640			reason = fmt.Sprintf("role %s cannot be updated in place", role.Name)
641		}
642		recorder.Eventf(roleSet, v1.EventTypeNormal, InPlaceFallbackEventType, "%s; falling back to recreate", reason)
643	}
644	
645	func recordInPlaceUpdateStarted(recorder record.EventRecorder, roleSet *orchestrationv1alpha1.RoleSet, role *orchestrationv1alpha1.RoleSpec, pod *v1.Pod) {
646		if recorder == nil {
647			return
648		}
649		recorder.Eventf(roleSet, v1.EventTypeNormal, InPlaceUpdateStartedEventType, "role %s pod %s in-place image update started", role.Name, pod.Name)
650	}
651	
652	func recordInPlaceUpdateCompleted(recorder record.EventRecorder, roleSet *orchestrationv1alpha1.RoleSet, role *orchestrationv1alpha1.RoleSpec, pod *v1.Pod) {
653		if recorder == nil {
654			return
655		}
656		recorder.Eventf(roleSet, v1.EventTypeNormal, InPlaceUpdateCompletedEventType, "role %s pod %s in-place image update completed", role.Name, pod.Name)
657	}
