659	// RolloutByStep performs rollout in steps based on the defined step size
660	func (s *StatelessRoleSyncer) RolloutByStep(ctx context.Context, roleSet *orchestrationv1alpha1.RoleSet, role *orchestrationv1alpha1.RoleSpec, currentStep int32) error {
661		var toCreate, toDelete []*v1.Pod
662		allPods, err := getRolePods(ctx, s.cli, roleSet.Namespace, roleSet.Name, role.Name)
663		if err != nil {
664			return err
665		}
666	
667		activePods, _ := filterActivePods(allPods)
668		expectedReplicas := getRoleReplicas(role)
669		// Calculate the expected number of updated Pods based on the step size
670		expectedUpdatedReplicas := utils.MinInt32((MaxSurge(role)+MaxUnavailable(role))*currentStep, expectedReplicas)
671		roleTemplateHash := s.computeHashFunc(&role.Template, nil)
672		updated, outdated := filterUpdatedPods(activePods, roleTemplateHash)
673		klog.Infof("[StatelessRoleSyncer.RolloutByStep] Step %d: roleset %s/%s role %s updated %d, outdated %d, expectedReplicas %d, expectedUpdatedReplicas %d, hash %s", currentStep, roleSet.Namespace, roleSet.Name, role.Name, len(updated), len(outdated), expectedReplicas, expectedUpdatedReplicas, roleTemplateHash)
674		if int32(len(updated)) >= expectedUpdatedReplicas {
675			return nil
676		}
677	
678		ready, _ := filterReadyPods(activePods)
679		// Calculate the number of Pods that can be safely deleted, considering both step constraints and maxUnavailable:
680		// - Step constraint: By the end of this step, we expect (expectedReplicas - expectedUpdatedReplicas) outdated Pods,
681		//   so we must avoid deleting too many.
682		deleteBudget := utils.MinInt32(int32(len(outdated))-expectedReplicas+expectedUpdatedReplicas, int32(len(ready))-expectedReplicas+MaxUnavailable(role))
683	
684		sortPodsByActive(outdated)
685		strategy := roleUpdateStrategyTypeOrDefault(role)
686		if strategy == orchestrationv1alpha1.InPlaceIfPossibleRoleUpdateStrategyType {
687			possible, reason, err := canRolloutPodsInPlace(roleSet, role, outdated, roleTemplateHash, s.computeHashFunc)
688			if err != nil {
689				return err
690			}
691			if possible {
692				selected := selectInPlaceOutdatedPodsForStep(outdated, roleTemplateHash, expectedUpdatedReplicas-int32(len(updated)))
693				return s.rolloutInPlace(ctx, roleSet, role, selected, roleTemplateHash, deleteBudget)
694			}
695			recordInPlaceFallback(s.recorder, roleSet, role, reason)
696		}
697		// 1. delete outdated pods
698		for i := 0; i < len(outdated); i++ {
699			if podutil.IsPodReady(outdated[i]) {
700				if deleteBudget <= 0 {
701					break
702				}
703				deleteBudget--
704			}
705			toDelete = append(toDelete, outdated[i])
706		}
707		// 2. created new pods
708		terminatingPods, _ := filterTerminatingPods(allPods)
709		terminatingPodCount := len(terminatingPods)
710		// take terminating pods into account
711		// Calculate how many Pods can be created, considering both step constraints and maxSurge:
712		// - Step constraint: By the end of this step, we aim to have expectedUpdatedReplicas new Pods,
713		//   so we must avoid creating more than necessary.
714		createBudget := utils.MinInt32(expectedReplicas+MaxSurge(role)-int32(len(activePods))-int32(terminatingPodCount), expectedUpdatedReplicas-int32(len(updated)))
715		for i := int32(0); i < createBudget; i++ {
716			pod, err := ctrlutil.GetPodFromTemplate(&role.Template, roleSet, metav1.NewControllerRef(roleSet, orchestrationv1alpha1.SchemeGroupVersion.WithKind(orchestrationv1alpha1.RoleSetKind)))
717			if err != nil {
718				return err
719			}
720			renderStormServicePod(roleSet, role, pod, nil)
721			toCreate = append(toCreate, pod)
722		}
723		klog.Infof("[StatelessRoleSyncer.RolloutByStep] Step %d: roleset %s/%s outdated %d, expectedReplicas %d, expectedUpdatedReplicas %d, deleteBudget %d, createBudget %d, allPods %d, toDelete %d, toCreate %d", currentStep, roleSet.Namespace, roleSet.Name, len(outdated), expectedReplicas, expectedUpdatedReplicas, deleteBudget, createBudget, len(allPods), len(toDelete), len(toCreate))
724		if _, err = createPodsInBatch(ctx, s.cli, toCreate); err != nil {
725			return err
726		}
727		if _, err = deletePodsInBatch(ctx, s.cli, toDelete); err != nil {
728			return err
729		}
730		return nil
731	}
732	
733	func selectInPlaceOutdatedPodsForStep(outdated []*v1.Pod, roleTemplateHash string, remaining int32) []*v1.Pod {
734		var selected []*v1.Pod
735		for _, pod := range outdated {
736			if pod.Annotations[constants.RoleInPlaceUpdateTargetHashAnnotationKey] == roleTemplateHash {
737				selected = append(selected, pod)
738				continue
739			}
740			if remaining <= 0 {
741				continue
742			}
743			selected = append(selected, pod)
744			remaining--
745		}
746		return selected
747	}
