749	func (s *StatelessRoleSyncer) AllReady(ctx context.Context, roleSet *orchestrationv1alpha1.RoleSet, role *orchestrationv1alpha1.RoleSpec) (bool, error) {
750		allPods, err := getRolePods(ctx, s.cli, roleSet.Namespace, roleSet.Name, role.Name)
751		if err != nil {
752			return false, err
753		}
754		activePods, inactivePods := filterActivePods(allPods)
755		if len(inactivePods) != 0 {
756			return false, nil
757		}
758		ready, notReady := filterReadyPods(activePods)
759		if len(notReady) != 0 {
760			return false, nil
761		}
762		updated, outdated := filterUpdatedPods(ready, s.computeHashFunc(&role.Template, nil))
763		if len(outdated) != 0 {
764			return false, nil
765		}
766		expectedReplicas := getRoleReplicas(role)
767		return len(updated) == int(expectedReplicas), nil
768	}
