770	// CheckCurrentStep determines which step the current role is in
771	func (s *StatelessRoleSyncer) CheckCurrentStep(ctx context.Context, roleSet *orchestrationv1alpha1.RoleSet, role *orchestrationv1alpha1.RoleSpec) (bool, int32, error) {
772		allPods, err := getRolePods(ctx, s.cli, roleSet.Namespace, roleSet.Name, role.Name)
773		if err != nil {
774			return false, 1, err
775		}
776	
777		// The step size defaults to MaxSurge(role) + MaxUnavailable(role)
778		stepLength := MaxSurge(role) + MaxUnavailable(role)
779		if stepLength < 1 {
780			stepLength = 1
781		}
782	
783		activePods, inactivePods := filterActivePods(allPods)
784		ready, notReady := filterReadyPods(activePods)
785	
786		// 'updated' contains ready Pods with the new version, while 'updatedActive' includes all new Pods regardless of readiness
787		roleTemplateHash := s.computeHashFunc(&role.Template, nil)
788		updated, outdated := filterUpdatedPods(ready, roleTemplateHash)
789		updatedActive, outdatedActive := filterUpdatedPods(activePods, roleTemplateHash)
790		klog.Infof("[StatelessRoleSyncer.CheckCurrentStep] roleset %s/%s role %s updatedReadyTotal: %d, outdatedReadyTotal: %d, updatedTotal: %d, outdatedTotal: %d",
791			roleSet.Namespace, roleSet.Name, role.Name, len(updated), len(outdated), len(updatedActive), len(outdatedActive))
792	
793		expectedReplicas := getRoleReplicas(role)
794	
795		// First, determine the minimum current step based on the number of ready Pods with the updated version
796		currentStep := int32(len(updated)-1)/stepLength + int32(1)
797	
798		// Then, consider whether we have already entered the next step. Handle the following cases:
799		// 1. Critical boundary where the current step is just completed:
800		//    (len(inactivePods) == 0 && len(notReady) == 0 && int32(len(updated)) == stepLength * currentStep)
801		// 2. The current step was already completed earlier, but no new Pod has become ready yet:
802		//    2.1 maxSurge is not allowed, so old Pods must be deleted first, resulting in:
803		//        int32(len(outdatedActive)) < expectedReplicas - stepLength * currentStep
804		//    2.2 maxUnavailable is not allowed, so new Pods are updated first, resulting in:
805		//        int32(len(updatedActive)) > stepLength * currentStep
806	
807		// Q: Why not use updatedActive and outdatedActive directly to determine the current step?
808		// A: To detect the exact boundary where the step has just completed.
809		//    The counts of updatedActive and outdatedActive alone are not sufficient to identify this state;
810		//    we must rely on the number of ready updated Pods.
811		if (len(inactivePods) == 0 && len(notReady) == 0 && int32(len(updated)) == stepLength*currentStep) ||
812			int32(len(updatedActive)) > stepLength*currentStep ||
813			int32(len(outdatedActive)) < expectedReplicas-stepLength*currentStep {
814			currentStep++
815		}
816	
817		allReady := len(inactivePods) == 0 &&
818			len(notReady) == 0 &&
819			len(outdated) == 0 &&
820			len(updated) >= int(expectedReplicas)
821	
822		return allReady, currentStep, nil
823	}
