837		}
838	
839		// Use existing pod-based syncers for podGroupSize <= 1
840		if role.Stateful {
841			return &StatefulRoleSyncer{
842				cli:             cli,
843				computeHashFunc: ctrlutil.ComputeHash,
844				recorder:        recorder,
845			}
846		}
847		return &StatelessRoleSyncer{
848			cli:             cli,
849			computeHashFunc: ctrlutil.ComputeHash,
850			recorder:        recorder,
851		}
852	}
853

