32	)
33	
34	type RollingManager interface {
35		Next(ctx context.Context, roleSet *orchestrationv1alpha1.RoleSet) error
36	}
37	
38	type RollingManagerSequential struct {
39		cli      client.Client
40		recorder record.EventRecorder
41	}
42	
43	func (m *RollingManagerSequential) Next(ctx context.Context, roleSet *orchestrationv1alpha1.RoleSet) (err error) {
44		// 1. ensure pod replica meet expectations
45		var scaling bool
46		for _, role := range roleSet.Spec.Roles {
47			klog.Infof("[RollingManagerSequential.Next] start to scale roleset %s/%s role %s", roleSet.Namespace, roleSet.Name, role.Name)
48			s, err := GetRoleSyncerWithRecorder(m.cli, &role, m.recorder).Scale(ctx, roleSet, &role)
49			if err != nil {
50				return err
51			}
52			scaling = scaling || s
53		}
54		if scaling {
55			klog.Infof("[RollingManagerSequential.Next] waiting for roleset %s/%s to be scaled", roleSet.Namespace, roleSet.Name)
56			return nil
57		}
58	
59		// 2. Sort roles by upgrade order
60		klog.Infof("[RollingManagerSequential.Next] sorting roleset roles by UpgradeOrder")
61		sortedRoles := sortRolesByUpgradeOrder(roleSet.Spec.Roles)
62		var sequenceLines []string
63		for i, role := range sortedRoles {
64			var orderStr string
65			if role.UpgradeOrder != nil {
66				orderStr = strconv.Itoa(int(*role.UpgradeOrder))
67			} else {
68				orderStr = "nil"
69			}
70			sequenceLines = append(sequenceLines, fmt.Sprintf("[%d] %s (Order=%s)", i+1, role.Name, orderStr))
71		}
72	
73		klog.Infof("[RollingManagerSequential.Next] Upgrade sequence for %s/%s:\n%s",
74			roleSet.Namespace,
75			roleSet.Name,
76			strings.Join(sequenceLines, "\n"))
77	
78		// 3. do the rollout process for each role by order
79		for _, role := range sortedRoles {
80			klog.Infof("[RollingManagerSequential.Next] start to rollout roleset %s/%s role %s", roleSet.Namespace, roleSet.Name, role.Name)
81			err := GetRoleSyncerWithRecorder(m.cli, &role, m.recorder).Rollout(ctx, roleSet, &role)
82			if err != nil {
83				return err
84			}
85			if ready, err := GetRoleSyncerWithRecorder(m.cli, &role, m.recorder).AllReady(ctx, roleSet, &role); err != nil {
86				return err
87			} else if !ready {
88				// each time we only update one role in sequential mode
89				klog.Infof("[RollingManagerSequential.Next] waiting for roleset %s/%s role %s's rollout process to be finished", roleSet.Namespace, roleSet.Name, role.Name)
90				break
91			}
92		}
93		return nil
94	}
95	
96	type RollingManagerParallel struct {
97		cli      client.Client
98		recorder record.EventRecorder
99	}
100	
101	func (m *RollingManagerParallel) Next(ctx context.Context, roleSet *orchestrationv1alpha1.RoleSet) (err error) {
102		// 1. ensure pod replica meet expectations
103		var scaling bool
104		for _, role := range roleSet.Spec.Roles {
105			klog.Infof("[RollingManagerParallel.Next] start to scale roleset %s/%s role %s", roleSet.Namespace, roleSet.Name, role.Name)
106			s, err := GetRoleSyncerWithRecorder(m.cli, &role, m.recorder).Scale(ctx, roleSet, &role)
107			if err != nil {
108				return err
109			}
110			scaling = scaling || s
111		}
112		if scaling {
113			klog.Infof("[RollingManagerParallel.Next] waiting for roleset %s/%s to be scaled", roleSet.Namespace, roleSet.Name)
114			return
115		}
116		// 2. do the rollout process for each role
117		for _, role := range roleSet.Spec.Roles {
118			klog.Infof("[RollingManagerParallel.Next] start to rollout roleset %s/%s role %s", roleSet.Namespace, roleSet.Name, role.Name)
119			err := GetRoleSyncerWithRecorder(m.cli, &role, m.recorder).Rollout(ctx, roleSet, &role)
120			if err != nil {
121				return err
122			}
123		}
124		return
125	}
126	
127	type RollingManagerInterleave struct {
128		cli      client.Client
129		recorder record.EventRecorder
130	}
131	
132	// Interleaved rollout: update roles in alternating steps,
133	// using (maxSurge + maxUnavailable) as the step size for all roles
134	func (m *RollingManagerInterleave) Next(ctx context.Context, roleSet *orchestrationv1alpha1.RoleSet) (err error) {
135		// 1. ensure pod replica meet expectations
136		var scaling bool
137		for _, role := range roleSet.Spec.Roles {
138			klog.Infof("[RollingManagerInterleave.Next] start to scale roleset %s/%s role %s", roleSet.Namespace, roleSet.Name, role.Name)
139			s, err := GetRoleSyncerWithRecorder(m.cli, &role, m.recorder).Scale(ctx, roleSet, &role)
140			if err != nil {
141				return err
142			}
143			scaling = scaling || s
144		}
145		if scaling {
146			klog.Infof("[RollingManagerInterleave.Next] waiting for roleset %s/%s to be scaled", roleSet.Namespace, roleSet.Name)
147			return nil
148		}
149		// 2. do the rollout process for each role
150		roleSteps := make(map[string]int32)
151		roleReadyStatus := make(map[string]bool)
152		currentStep := int32(math.MaxInt32)
153		allRolesReady := true
154	
155		// Check the current step for each role and determine the minimum step across all roles as the global current step
156		for _, role := range roleSet.Spec.Roles {
157			allReady, currentRoleStep, err := GetRoleSyncerWithRecorder(m.cli, &role, m.recorder).CheckCurrentStep(ctx, roleSet, &role)
158			if err != nil {
159				klog.Errorf("[RollingManagerInterleave.Next] Failed to get current step for role %s in roleset %s/%s: %v", role.Name, roleSet.Namespace, roleSet.Name, err)
160				continue
161			}
162			// Store each role's step and readiness status in a map to avoid redundant calculations later
163			roleSteps[role.Name] = currentRoleStep
164			roleReadyStatus[role.Name] = allReady
165			if allReady {
166				klog.Infof("[RollingManagerInterleave.Next] Role %s in roleset %s/%s is already ready", role.Name, roleSet.Namespace, roleSet.Name)
167				continue
168			} else {
169				allRolesReady = false
170				if currentRoleStep < currentStep {
171					currentStep = currentRoleStep
172				}
173			}
174			klog.Infof("[RollingManagerInterleave.Next] Role %s in roleset %s/%s has possible current step: %d", role.Name, roleSet.Namespace, roleSet.Name, currentRoleStep)
175		}
176	
177		// If all roles are ready, the rollout is complete
178		if allRolesReady {
179			klog.Infof("[RollingManagerInterleave.Next] roleset %s/%s all roles' rollout step %d finished",
180				roleSet.Namespace, roleSet.Name, currentStep)
181			return nil
182		}
183		if currentStep == int32(math.MaxInt32) {
184			currentStep = int32(1)
185		}
186		klog.Infof("[RollingManagerInterleave.Next] Final current step for roleset %s/%s: %d",
187			roleSet.Namespace, roleSet.Name, currentStep)
188	
189		for _, role := range roleSet.Spec.Roles {
190			// Skip roles that are already fully ready
191			if roleReadyStatus[role.Name] {
192				continue
193			}
194			// Skip roles that have already passed the current global step
